(window.TNQ=window.TNQ||[]).push({"terms":{"관습법":{"d":"관행이 계속 반복되고 이에 대한 법적 확신이 형성되어 법원으로서 효력을 가지는 불문법이다.","r":[]},"조리":{"d":"사물의 이치와 상식에 따른 판단 기준으로, 법률과 관습법이 모두 없을 때 적용되는 법원.","r":["관습법"]},"강행규정":{"d":"당사자의 합의로 배제하거나 바꿀 수 없는 규정으로 위반하면 무효이다.","r":[]},"임의규정":{"d":"당사자가 다르게 정하면 그 의사가 우선하는 규정.","r":["강행규정"]},"사정변경의 원칙":{"d":"계약 성립 후 기초가 된 사정이 현저히 변하여 이행이 부당한 경우 계약의 해제나 해지를 허용하는 원칙으로 엄격히 인정된다.","r":[]},"실효의 원칙":{"d":"권리자가 오랜 기간 권리를 행사하지 않아 상대방이 더 이상 행사하지 않으리라고 믿게 되면 그 행사를 허용하지 않는 원칙이다.","r":[]},"권리남용":{"d":"권리 행사가 외형상 정당해 보이나 신의칙에 반하여 상대방에게 부당한 손해를 입히려는 목적인 경우 허용되지 않는 것이다.","r":[]},"형성권":{"d":"권리자의 일방적 의사표시만으로 법률관계의 발생, 변경, 소멸을 일으키는 권리이다. 취소권, 추인권, 해지권 등이 있다.","r":[]},"항변권":{"d":"상대방의 청구에 대하여 이행을 거절할 수 있는 권리.","r":["형성권"]},"원시취득":{"d":"타인의 권리에 기초하지 않고 권리를 새로 취득하는 것.","r":["승계취득"]},"승계취득":{"d":"타인의 권리에 기초하여 권리를 취득하는 것으로 이전적 승계와 설정적 승계가 있다.","r":[]},"제한능력자":{"d":"미성년자, 피한정후견인, 피성년후견인처럼 단독으로 완전한 법률행위를 할 수 없는 자이다.","r":[]},"성년후견":{"d":"질병, 장애, 노령 등으로 사무 처리 능력이 지속적으로 결여된 사람을 위해 법원이 개시하는 후견제도이다.","r":[]},"한정후견":{"d":"사무 처리 능력이 부족한 사람을 위해 한정후견인의 동의가 필요한 행위의 범위를 법원이 정하는 후견제도이다.","r":[]},"특정후견":{"d":"일시적 후원 또는 특정 사무에 대한 후원이 필요한 사람을 위해 법원이 기간 또는 사무의 범위를 정하는 후견제도이다.","r":[]},"현존이익":{"d":"받은 이익이 그대로 또는 모습을 바꾸어 현재 남아 있는 한도의 이익이다. 선의의 반환 범위를 정하는 기준이다.","r":[]},"실종선고":{"d":"부재자의 생사가 일정 기간 분명하지 않을 때 법원이 사망한 것으로 보는 제도이다.","r":[]},"재산관리인":{"d":"부재자의 재산을 관리하기 위해 부재자가 정하거나 법원이 선임한 사람이다.","r":[]},"사단법인":{"d":"일정한 목적을 위해 모인 사람의 단체를 기초로 설립되는 법인이다.","r":[]},"재단법인":{"d":"일정한 목적을 위해 출연된 재산을 중심으로 설립되는 법인이다.","r":[]},"정관":{"d":"법인의 조직과 활동에 관한 근본 규칙 또는 그 규칙을 적은 서면이다.","r":[]},"주무관청":{"d":"법인 설립의 허가 등 감독 권한을 가진 행정관청이다.","r":[]},"비법인사단":{"d":"실질은 사단이나 법인격이 없는 단체로, 종중과 교회가 그 예이다.","r":[]},"총유":{"d":"단체의 구성원이 지분 없이 공동으로 재산을 소유하고 관리와 처분을 총회에서 정하는 형태.","r":["비법인사단"]},"종물":{"d":"주물의 상용에 이바지하기 위해 주물에 부속시킨 독립한 물건이다.","r":[]},"주물":{"d":"종물에 의해 상용에 이바지함을 받는 중심이 되는 물건이다.","r":[]},"단독행위":{"d":"한 사람의 일방적 의사표시만으로 성립하는 법률행위이다. 상계, 유언, 소유권의 포기가 그 예이다.","r":[]},"준법률행위":{"d":"의사표시가 아니라 법률의 규정에 의하여 효과가 생기는 행위로, 채무의 승인과 채권양도의 통지가 그 예이다.","r":[]},"통정허위표시":{"d":"상대방과 짜고 진의 없이 한 허위의 의사표시로 무효이다. 선의의 제3자에게는 대항하지 못한다.","r":[]},"불공정한 법률행위":{"d":"궁박, 경솔, 무경험을 이용해 현저히 균형을 잃은 대가를 약정한 법률행위로 무효이다.","r":[]},"궁박":{"d":"급박한 곤궁을 말하며 경제적 원인뿐 아니라 심리적 원인에 기인할 수도 있다.","r":[]},"무경험":{"d":"어느 특정 영역이 아닌 거래 일반에 대한 경험 부족을 뜻한다.","r":[]},"착오":{"d":"표의자가 진의와 표시의 불일치를 알지 못하고 한 의사표시로 중요 부분에 착오가 있으면 취소할 수 있다.","r":[]},"무권대리":{"d":"대리권 없는 자가 대리인으로서 한 행위로, 본인이 추인하지 않으면 본인에게 효력이 없다.","r":[]},"표현대리":{"d":"대리권이 없는데도 있는 것처럼 믿을 외관이 있어 본인에게 책임을 지우는 제도.","r":["무권대리"]},"복대리":{"d":"대리인이 자기 이름으로 다시 선임한 복대리인이 본인을 직접 대리하는 것.","r":["무권대리"]},"정지조건":{"d":"법률행위의 효력 발생을 장래의 불확실한 사실에 걸어 둔 조건이다. 성취한 때부터 효력이 생긴다.","r":[]},"해제조건":{"d":"성취되면 이미 생긴 법률행위의 효력이 소멸하는 조건이다.","r":[]},"초일불산입":{"d":"기간을 일, 주, 월, 년으로 정한 때 첫날을 계산에 넣지 않는 원칙이다. 오전 영시에 시작하면 예외이다.","r":[]},"소멸시효":{"d":"권리자가 일정 기간 권리를 행사하지 않으면 그 권리가 소멸하는 제도이다. 완성되면 기산일로 소급한다.","r":[]},"제척기간":{"d":"권리의 존속기간으로, 중단이 없고 법원이 직권으로 고려하며 기산일부터 소급하지 않는다.","r":[]},"청산인":{"d":"해산한 법인의 청산 사무를 맡아 처리하는 자이다. 해산 시 이사가 당연히 된다.","r":[]},"임시이사":{"d":"이사가 없거나 부족하여 손해가 생길 염려가 있을 때 법원이 선임하는 임시 이사이다.","r":[]},"특별대리인":{"d":"법인과 이사의 이익이 충돌하는 사항에서 법인을 대표하도록 선임하는 대리인.","r":["임시이사"]},"물권적 청구권":{"d":"물권의 내용 실현이 방해되거나 방해될 염려가 있을 때 방해 제거 등을 청구할 수 있는 권리로 형성권이 아니다.","r":[]},"동시이행항변권":{"d":"쌍무계약에서 상대방이 채무를 이행하거나 이행을 제공할 때까지 자기의 채무 이행을 거절할 수 있는 권리이다.","r":[]},"신의칙":{"d":"법률관계의 당사자가 상대방의 이익을 고려하여 신의에 따라 성실하게 권리를 행사하고 의무를 이행해야 한다는 원칙이다.","r":[]},"추인":{"d":"효력이 불확정이거나 흠 있는 법률행위를 사후에 인정하여 유효하게 하는 의사표시이다.","r":[]},"사실인 관습":{"d":"법적 확신이 없어 관습법은 아니지만 법률행위의 해석 기준이나 의사 보충의 자료가 되는 관습이다.","r":[]},"분묘기지권":{"d":"타인의 토지에 분묘를 설치한 자가 그 분묘를 소유하기 위해 토지를 사용할 수 있는 관습법상 지상권에 유사한 물권이다.","r":[]},"관습법상의 물권":{"d":"관습에 의해 법적 확신을 얻어 인정되는 물권이다.","r":[]},"행위능력":{"d":"단독으로 유효하게 법률행위를 할 수 있는 지위나 자격이다.","r":[]},"법정대리인":{"d":"법률의 규정이나 법원의 선임 등으로 대리권을 가지는 대리인이다. 친권자와 후견인이 그 예이다.","r":[]},"피성년후견인":{"d":"성년후견개시의 심판을 받은 사람으로 그의 법률행위는 원칙적으로 취소할 수 있다.","r":[]},"피한정후견인":{"d":"한정후견개시의 심판을 받은 사람으로 한정후견인의 동의가 필요한 행위의 범위가 법원에 의해 정해진다.","r":[]},"의사무능력자":{"d":"자기 행위의 의미나 결과를 합리적으로 판단할 수 있는 정신적 능력이 없는 자로 그의 법률행위는 무효이다.","r":[]},"소비대차계약":{"d":"당사자 일방이 금전 기타 대체물의 소유권을 이전하고 상대방이 같은 종류, 품질, 수량으로 반환할 것을 약정하는 계약이다.","r":[]},"부재자":{"d":"종래의 주소나 거소를 떠나 쉽게 돌아올 가망이 없어 그의 재산 관리가 필요한 사람이다.","r":[]},"권한을 넘는 행위":{"d":"재산관리인이 보존행위, 이용행위, 개량행위의 범위를 넘어 처분하는 행위로 법원의 허가가 필요하다.","r":[]},"실종기간":{"d":"부재자의 생사가 분명하지 않은 채로 경과해야 하는 법정 기간으로 이 기간 만료 시 사망한 것으로 본다.","r":[]},"이해관계인":{"d":"어떤 법률관계에서 법률상 이해관계를 가진 사람이다.","r":[]},"필요적 기재사항":{"d":"정관에 반드시 적어야 하는 사항으로 하나라도 빠지면 정관은 무효가 된다.","r":[]},"사원권":{"d":"사단법인의 구성원인 사원이 법인에 대하여 가지는 권리와 의무를 포괄하는 지위이다.","r":[]},"청산법인":{"d":"해산한 뒤 청산의 목적 범위에서만 권리의무를 가지고 존속하는 법인이다.","r":[]},"대표권":{"d":"법인을 대표하여 대외적으로 행위를 하고 그 효과를 법인에 귀속시킬 수 있는 권한이다.","r":[]},"법인의 불법행위":{"d":"법인의 대표자가 직무에 관하여 타인에게 손해를 가한 경우 법인이 배상책임을 지는 것이다.","r":[]},"천연과실":{"d":"물건의 용법에 의하여 수취하는 산출물이다.","r":[]},"반사회적 법률행위":{"d":"선량한 풍속 기타 사회질서에 위반한 법률행위로, 절대적으로 무효이다.","r":[]},"무효행위의 전환":{"d":"무효인 법률행위가 다른 법률행위의 요건을 갖춘 경우 그 다른 행위로서 효력을 갖게 하는 것이다.","r":[]},"선의의 제3자":{"d":"허위표시 등 무효 사유를 알지 못하고 새로운 법률상 이해관계를 맺은 제3자이다.","r":[]},"가장양도인":{"d":"허위표시로 재산을 양도한 것처럼 가장한 자이다.","r":[]},"채권자취소권":{"d":"채무자가 채권자를 해함을 알면서 한 재산권을 목적으로 한 법률행위의 취소를 법원에 청구할 수 있는 권리이다.","r":[]},"진의 아닌 의사표시":{"d":"표의자가 진의 아님을 알고 한 의사표시이다. 원칙적으로 유효하나 상대방이 알았거나 알 수 있었으면 무효이다.","r":[]},"진의":{"d":"의사표시를 하는 사람이 마음속에 가진 진짜 뜻이다.","r":[]},"중대한 과실":{"d":"현저하게 주의를 게을리하여 거의 고의에 가까운 정도의 과실이다.","r":[]},"표의자":{"d":"의사표시를 하는 사람으로 착오, 사기, 강박 등에서 취소권을 행사하는 쪽이다.","r":[]},"하자담보책임":{"d":"매매의 목적물에 숨은 하자가 있을 때 매도인이 매수인에게 지는 책임이다.","r":[]},"사기에 의한 의사표시":{"d":"타인의 기망행위로 착오에 빠져 한 의사표시로 취소할 수 있다.","r":[]},"기망행위":{"d":"고의로 거짓을 말하거나 사실을 숨겨 상대방을 착오에 빠뜨리는 행위이다.","r":[]},"고지의무":{"d":"신의칙상 상대방에게 중요한 사실을 알려야 하는 의무로 이를 알리지 않으면 부작위에 의한 기망이 될 수 있다.","r":[]},"제3자에 의한 사기":{"d":"상대방이 아닌 제3자가 기망을 행한 경우로 상대방이 그 사실을 알았거나 알 수 있었을 때만 취소할 수 있다.","r":[]},"사용자책임":{"d":"피용자가 업무 집행 중 타인에게 손해를 가했을 때 사용자가 지는 배상책임이다.","r":[]},"강박":{"d":"해악을 고지하여 공포심을 일으켜 의사표시를 하게 하는 것이다.","r":[]},"취소권":{"d":"취소할 수 있는 법률행위를 소급하여 무효로 만들 수 있는 권리이다. 추인할 수 있는 날부터 기간 제한을 받는다.","r":[]},"수권행위":{"d":"본인이 대리인에게 대리권을 주는 행위로, 대리권 수여의 원인이 되는 법률행위이다.","r":[]},"임의대리":{"d":"본인의 수권행위로 대리권이 생기는 대리이다.","r":[]},"복대리인":{"d":"대리인이 자신의 권한 범위 안에서 선임한 본인의 대리인으로, 대리인의 대리인이 아니다.","r":[]},"개량행위":{"d":"물건의 성질을 변하지 않게 하면서 그 이용가치나 교환가치를 늘리는 행위이다.","r":[]},"원인된 법률관계":{"d":"대리권 수여의 원인이 된 위임, 고용 등의 기초 법률관계이다.","r":[]},"복임권":{"d":"대리인이 자기 이름으로 다시 대리인을 선임할 수 있는 권한이다. 임의대리인은 제한적으로만 가진다.","r":[]},"권한을 넘은 표현대리":{"d":"대리인이 기본대리권 외의 행위를 했는데 상대방이 권한이 있다고 믿을 정당한 이유가 있으면 본인이 책임지는 제도이다.","r":[]},"기본대리권":{"d":"권한을 넘은 표현대리가 성립하려면 먼저 있어야 하는 대리인의 원래 대리권이다.","r":[]},"대리권소멸 후의 표현대리":{"d":"대리권이 소멸한 뒤 이전 대리인이 한 행위에 대해, 상대방이 선의 무과실이면 본인이 책임지는 표현대리이다.","r":[]},"대리권 수여의 표시":{"d":"본인이 제3자에게 대리권을 주었다고 표시한 경우로, 표현대리의 한 유형이다.","r":[]},"최고":{"d":"상대방에게 일정한 행위를 하라고 요구하는 통지이다. 무권대리에서는 추인 여부의 확답을 요구할 때 쓴다.","r":[]},"철회권":{"d":"무권대리의 상대방이 본인의 추인이 있기 전에 계약을 거두어들일 수 있는 권리이다. 상대방이 선의일 때만 행사할 수 있다.","r":[]},"전득자":{"d":"상대방으로부터 권리를 다시 넘겨받은 제3자이다.","r":[]},"과실상계":{"d":"손해 발생에 피해자의 과실도 있을 때 배상액을 줄이는 제도이다.","r":[]},"법정추인":{"d":"취소권자가 이의 없이 이행, 이행청구, 양도 등 일정한 행위를 하면 추인한 것으로 보는 제도이다.","r":[]},"무효행위의 추인":{"d":"무효인 법률행위를 무효임을 알고 추인하면 새로운 법률행위를 한 것으로 보는 제도이다. 소급효는 없다.","r":[]},"유동적 무효":{"d":"토지거래허가를 받기 전의 계약처럼 허가를 받으면 소급하여 유효가 되고 못 받으면 확정적으로 무효가 되는 상태이다.","r":[]},"의사무능력":{"d":"자기 행위의 결과를 판단할 정신능력이 없는 상태로, 그 상태에서 한 법률행위는 무효이다.","r":[]},"추인할 수 있는 날":{"d":"취소 원인이 종료되어 취소권자가 추인할 수도 취소할 수도 있게 된 때이다.","r":[]},"만료":{"d":"정해진 기간의 끝에 이르러 그 효력이 다하는 것이다.","r":[]},"기산점":{"d":"기간이나 시효를 계산하기 시작하는 시점이다.","r":[]},"시효이익":{"d":"시효가 완성됨으로써 의무자가 받는 이익이다. 완성 전에 미리 포기할 수 없다.","r":[]},"시효완성의 항변":{"d":"시효가 완성되었다고 당사자가 소송에서 주장하는 것으로, 이를 원용하지 않으면 법원은 시효로 재판하지 못한다.","r":[]},"원용":{"d":"시효의 이익을 받겠다는 뜻을 소송 등에서 주장하는 것이다.","r":[]},"시효중단":{"d":"청구, 압류나 가압류, 승인이 있으면 이미 진행한 시효기간이 효력을 잃고 중단 사유가 끝난 때부터 새로 진행하는 제도이다.","r":[]},"재판상의 청구":{"d":"소 제기 등으로 재판을 통해 권리를 주장하는 것으로 시효중단 사유이다. 각하, 기각, 취하되면 효력이 없다.","r":[]},"지급명령":{"d":"금전 채권에 대해 채무자 심문 없이 법원이 채무 이행을 명하는 간이 절차이다. 시효중단 사유가 된다.","r":[]},"가압류":{"d":"금전 채권의 집행을 보전하려고 채무자의 재산을 미리 동결해 두는 보전처분이다. 시효중단 사유가 된다.","r":[]},"피보전채권":{"d":"가압류나 가처분으로 보전하려는 대상이 되는 채권이다.","r":[]},"응소":{"d":"상대방이 제기한 소송에 피고로서 대응하는 것이다.","r":[]},"동시이행의 항변권":{"d":"쌍무계약에서 상대방이 이행을 제공할 때까지 자기 채무의 이행을 거절할 수 있는 권리이다.","r":[]},"선택채권":{"d":"여러 개의 급부 중 선택에 따라 정해지는 채권이다.","r":[]},"불확정기한":{"d":"도래는 확실하지만 그 시기를 알 수 없는 기한이다.","r":[]},"불능조건":{"d":"성립 당시 이미 성취할 수 없는 조건이다. 정지조건이면 법률행위가 무효이고 해제조건이면 조건 없는 법률행위가 된다.","r":[]},"불법조건":{"d":"조건 자체가 선량한 풍속이나 사회질서에 반하는 조건이며, 이를 붙인 법률행위는 무효이다.","r":[]},"시기":{"d":"법률행위 효력의 발생 시점을 정한 기한이다.","r":[]},"종기":{"d":"법률행위 효력의 소멸 시점을 정한 기한이다.","r":[]},"기한의 이익":{"d":"기한이 있음으로써 당사자가 받는 이익이다. 특약이 없으면 채무자를 위한 것으로 추정한다.","r":[]},"기한이익 상실":{"d":"채무자가 담보를 손상하는 등의 사유가 있어 기한의 이익을 잃고 즉시 이행해야 하는 것이다.","r":[]},"사인증여":{"d":"증여자의 사망으로 효력이 생기는 증여로, 유증에 관한 규정을 준용한다.","r":[]},"상계":{"d":"서로 같은 종류의 채권을 가진 당사자가 대등액에서 채무를 소멸시키는 일방적 의사표시이다.","r":[]},"경개계약":{"d":"기존 채무를 소멸시키고 새로운 채무를 성립시키는 계약이다.","r":[]},"부제소합의":{"d":"당사자가 특정 권리에 관해 소를 제기하지 않기로 하는 합의이다.","r":[]},"공시송달":{"d":"상대방의 주소를 알 수 없을 때 법원 게시 등으로 송달한 것으로 보는 제도이다.","r":[]},"수령능력":{"d":"의사표시를 받아 그 내용을 이해할 수 있는 능력으로, 제한능력자에게는 인정되지 않는 것이 원칙이다.","r":[]},"총유물":{"d":"비법인사단의 사원이 총유하는 재산이다. 처분과 관리는 사원총회 결의로 한다.","r":[]},"지분권":{"d":"공동소유자가 공유물에 대해 가지는 몫에 해당하는 권리이다.","r":[]}},"notes":{"1심 판결에서 패소한 자가 항소심 판결 선고 전에 패소를 예상하고 한 법률행위는 항소심에서 승소하였더라도 장래 결과에 대한 예측이므로 착오를 이유로 취소할 수 없다":"패소를 예상해 한 행위는 미래 결과에 대한 예측일 뿐이어서 나중에 승소해도 착오로 취소하지 못합니다.","1주간 전에 회의의 목적사항을 기재한 통지를 발하고 그 밖에 정관에 정한 방법에 의한다":"총회 1주간 전에 회의 목적을 적은 통지를 보내고 그 밖의 방식은 정관에 정한 대로 합니다.","2004년 5월 16일 출생자는 출생일을 산입하므로 2023년 5월 15일 24시에 19세(성년)가 된다":"출생일을 포함해 세기 때문에 태어난 날의 전날 24시에 만 19세가 되어 성년이 됩니다.","2024년 4월에 ‘2024년 제12회 행정사 시험에 응시하여 최종 합격하면 자동차를 사준다’는 법률행위는 정지조건부 법률행위이다":"합격이라는 불확실한 사실이 이뤄져야 자동차를 사 줄 의무가 생기므로 정지조건부 법률행위입니다.","2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 추정한다":"같은 사고로 두 사람 이상이 숨지면 누가 먼저 죽었는지 따지지 않고 동시에 죽은 것으로 추정합니다.","6월 1일 24시에 만료한다":"개월로 정한 기간은 첫날을 빼고 달력으로 세어 해당하는 날의 전날 끝에 만료합니다.","6월 4일 16시에 만료한다":"시간 단위 기간은 곧바로 세기 시작하므로 정한 시간이 흐른 바로 그 시각에 끝납니다.","6월 내에 재판상의 청구, 파산절차참가, 화해를 위한 소환, 임의출석, 압류 또는 가압류, 가처분을 하지 아니하면 시효중단의 효력이 없다":"최고는 6월 안에 소송이나 압류 같은 후속 조치를 해야만 시효를 중단시키는 효력이 인정됩니다.","① 대표기관(이사 기타 대표자)의 행위 ② 직무에 관한 행위 ③ 일반 불법행위 요건 충족(고의·과실, 위법성, 손해, 인과관계, 책임능력)":"대표기관이 직무에 관해 한 행위가 일반 불법행위의 요건까지 갖췄을 때 법인의 책임이 생깁니다.","① 보존행위 ② 대리의 목적인 물건이나 권리의 성질을 변하지 아니하는 범위에서 이용 또는 개량하는 행위만 할 수 있다":"대리권의 범위가 정해지지 않았다면 보존행위와 성질이 변하지 않는 범위의 이용과 개량만 할 수 있습니다.","① 본인의 사망 ② 대리인의 사망, 성년후견의 개시 또는 파산":"본인이 죽거나 대리인이 죽거나 성년후견이 시작되거나 파산하면 대리권이 사라집니다.","① 주물의 상용에 공할 것(주물 자체의 효용에 이바지)":"종물이 되려면 주물을 계속 쓰는 데 이바지해야 하고 주물 자체의 효용을 높여야 합니다.","① 현존사무의 종결 ② 채권의 추심 및 채무의 변제 ③ 잔여재산의 인도. 직무를 행하기 위하여 필요한 모든 행위를 할 수 있다":"청산인은 남은 일 마무리, 채권 추심과 채무 변제, 잔여재산 인도를 위해 필요한 행위를 모두 할 수 있습니다.","② 주물에 부속된 관계(장소적 밀접성)":"종물은 주물과 장소적으로 가까이 붙어 있어 하나처럼 쓰이는 관계여야 합니다.","④ 주물과 종물이 동일한 소유자에 속할 것":"주물과 종물의 소유자가 같아야 하므로 남의 물건은 종물이 될 수 없습니다.","가압류의 피보전채권에 관하여 본안의 승소판결이 확정되어도 가압류에 의한 시효중단의 효력은 당연히 소멸하지 않는다(가압류 집행보전의 효력이 존속하는 동안 계속된다)":"본안에서 이겨 판결이 확정돼도 가압류에 의한 중단 효력은 사라지지 않고 가압류의 집행보전 효력이 있는 동안 이어집니다.","가장매매의 매수인으로부터 그와의 매매계약에 의한 소유권이전청구권 보전을 위한 가등기를 마친 자":"가장매매의 매수인에게서 사들이고 가등기까지 한 사람은 겉모습을 믿은 제삼자로 보호됩니다.","가장 매수인(丙)이 악의라도 그로부터 매수한 전득자(丁)가 선의이면 甲은 丁에게 무효를 주장하여 이전등기의 말소를 구할 수 없다":"가장 매수인이 악의여도 그에게서 산 전득자가 선의면 원래 매도인은 무효를 내세워 등기를 말소할 수 없습니다.","가장소비대차에서 대주의 계약상 지위를 이전받은 자":"허위로 꾸민 대여에서 빌려준 사람의 지위를 넘겨받은 사람은 새로운 이해관계가 아니라 제삼자로 보지 않습니다.","가장양도인의 가장양수인에 대한 권리를 채권자대위권으로 행사하는 채권자":"채권자대위권으로 가장양도인의 권리를 행사하는 채권자는 독자적 이해관계가 없어 제삼자가 아닙니다.","가장 저당권자, 가장 근저당권의 피담보채권을 가압류한 자":"가장 저당권의 피담보채권을 가압류한 사람은 새로 법률상 이해관계를 맺은 제삼자에 해당합니다.","가장채권의 가압류권자, 가장 매수인의 전득자":"가장채권을 가압류한 사람과 가장 매수인에게서 다시 산 전득자도 보호받는 제삼자입니다.","가정법원은 성년후견개시의 심판을 할 때 본인의 의사를 고려하여야 한다":"성년후견을 시작할지 정할 때 본인이 어떻게 원하는지를 법원이 반드시 참작해야 합니다.","가정법원은 피한정후견인이 한정후견인의 동의를 받아야 하는 행위의 범위를 정할 수 있다":"한정후견에서는 어떤 행위에 후견인 동의가 필요한지 가정법원이 범위를 정해 줍니다.","가처분명령에 다른 정함이 없으면 법인의 통상사무에 속하지 않는 행위를 하지 못한다. 법원의 허가를 얻은 경우는 예외이다. 위반한 행위에도 법인은 선의의 제3자에 대하여 책임을 진다":"직무대행자는 통상사무 밖의 행위를 못 하며, 어겨도 모르고 거래한 제삼자에게 법인이 책임집니다.","각 사원의 결의권은 평등하다. 사원은 서면이나 대리인으로 결의권을 행사할 수 있다. 정관에 다른 규정이 있으면 적용하지 않는다":"사원은 출자액과 관계없이 한 표씩이며, 직접 오지 않고 서면이나 대리인으로도 의결권을 씁니다.","감사는 재산상황의 부정을 총회에 보고하기 위하여 필요하면 임시총회를 소집할 권한이 있다":"감사는 부정을 보고할 필요가 있으면 이사에게 맡기지 않고 스스로 임시총회를 소집할 수 있어요.","강박에 의한 의사표시의 취소권 행사기간은 제척기간(제146조)이다. 소멸시효가 아니다":"강박으로 인한 취소권의 행사 기간은 중단이 없는 제척기간이고 소멸시효가 아닙니다.","강제집행을 면하려는 허위 근저당권설정등기(통정허위표시의 문제)":"강제집행을 피하려는 허위 등기는 반사회성 문제가 아니라 상대와 짜고 한 통정허위표시로 다룹니다.","강행규정(선량한 풍속 기타 사회질서에 관계있는 규정)에 어긋나는 내용으로는 적용되지 않는다":"사회질서와 관련된 강행규정에 어긋나는 관습은 당사자가 따르기로 해도 적용되지 않습니다.","강행규정에 위반하여 무효인 계약에는 상대방이 선의·무과실이더라도 표현대리의 법리가 적용되지 않는다":"강행규정 위반으로 무효인 계약은 상대가 선의이고 무과실이어도 표현대리로 살릴 수 없습니다.","강행규정을 위반한 약정을 한 자가 스스로 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다":"강행규정을 어긴 약정을 한 사람이 무효를 주장해도 특별한 사정이 없으면 신의칙 위반이 아닙니다.","강행규정을 위반한 약정의 무효를 그 약정을 한 자가 스스로 주장하는 것. 공익적 요구인 합법성의 원칙이 신의칙에 우선한다":"강행규정을 어긴 사람도 스스로 무효를 주장할 수 있으며 합법성의 원칙이 신의칙을 앞섭니다.","개시 원인이 소멸한 경우 가정법원이 본인, 배우자, 4촌 이내의 친족, 성년후견인, 성년후견감독인, 검사, 지방자치단체의 장의 청구에 의하여 종료 심판을 한다":"후견이 필요하던 사유가 사라지면 청구를 받은 가정법원이 종료 심판으로 후견을 끝냅니다.","개시 원인이 소멸한 경우 본인, 배우자, 4촌 이내의 친족, 한정후견인, 한정후견감독인, 검사, 지방자치단체의 장의 청구에 의한 심판":"한정후견도 개시 사유가 없어지면 청구에 따른 법원의 심판으로 끝이 납니다.","객관적으로 권리행사로 인한 권리자의 이익과 상대방의 불이익 사이에 현저한 불균형이 있어야 하고, 주관적으로 권리행사의 목적이 상대방에게 고통·손해를 주려는 데 있어야 한다(판례)":"권리자 이익보다 상대 손해가 훨씬 크고, 목적도 상대를 괴롭히려는 데 있어야 권리남용이 됩니다.","객관적으로 급부와 반대급부 사이에 현저한 불균형이 있고, 주관적으로 피해 당사자의 궁박·경솔·무경험 중 어느 하나가 있으며, 상대방이 이를 알고 이용하려는 의사가 있어야 한다":"주고받는 가치가 크게 어긋나고, 피해자의 약점이 있고, 상대가 이를 알고 이용하려 했을 때 불공정한 법률행위가 됩니다.","건물은 토지와 별개의 독립한 부동산이다. 최소한의 기둥과 지붕 및 주벽이 있으면 독립한 건물로 인정될 수 있다":"건물은 땅에 붙어 있어도 토지와 따로 거래되는 부동산이며 기둥과 지붕과 주벽만 있어도 건물로 봅니다.","경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다":"대리로 거래했다면 경솔과 무경험은 대리인에게서, 궁박은 본인의 상황에서 판단합니다.","계약은 본인의 추인이 있을 때까지 상대방이 본인이나 그 대리인에 대하여 철회할 수 있다. 계약 당시 상대방이 대리권 없음을 안 때에는 철회할 수 없다":"상대는 본인이 추인하기 전까지 계약을 철회할 수 있지만 대리권 없음을 알고 계약했다면 철회하지 못합니다.","계약이 해제된 후에도 해제의 상대방은 해제로 인한 불이익을 면하기 위하여 착오 등을 이유로 취소권을 행사하여 계약 전체를 무효로 돌릴 수 있다":"해제를 당한 상대방도 해제 이후에 착오 등으로 취소하면 계약 전체를 처음부터 무효로 만들 수 있습니다.","고객의 안전을 배려할 보호의무를 진다":"숙박업자는 투숙객이 안전하게 머물도록 배려할 의무를 부담하는 위치에 있습니다.","고지의무가 있는 사람이 알리지 않고 일부러 침묵하면 기망행위가 될 수 있다. 고지의무는 법령·계약뿐 아니라 신의칙·조리상으로도 인정된다":"알릴 의무가 있는 사람이 일부러 침묵하면 기망이 되고, 그 의무는 법령과 계약 외에 신의칙에서도 생깁니다.","공고에는 채권자가 기간 내에 신고하지 아니하면 청산에서 제외될 것을 표시하여야 한다. 공고는 법원의 등기사항 공고와 동일한 방법으로 한다":"공고문에는 기간 안에 신고하지 않으면 청산에서 제외된다는 경고를 적고 등기 공고와 같은 방법으로 냅니다.","과실은 물건에서 생기는 것이다. 권리의 과실은 민법상 과실이 아니다":"민법의 과실은 물건에서 나오는 수익만 가리키므로 권리에서 나오는 이익은 포함되지 않습니다.","광고·선전에 다소의 과장이나 허위가 수반되는 것은 일반 상거래의 관행과 신의칙에 비추어 시인될 수 있는 한 기망성이 결여된다":"광고의 다소 과장은 거래 관행과 신의칙상 용인되는 범위라면 속이는 행위로 보지 않습니다.","교환계약의 당사자가 자기 소유 목적물의 시가를 묵비하는 것은 특별한 사정이 없는 한 기망행위가 되지 않는다":"교환할 때 자기 물건의 시가를 말하지 않은 것만으로는 특별한 사정이 없으면 속이는 행위로 보지 않습니다.","교회가 의결권 있는 교인 3분의 2 이상의 찬성으로 소속 교단을 탈퇴한 경우 종전 교회의 재산은 탈퇴한 교회 소속 교인들의 총유로 귀속된다":"교인 3분의 2 이상이 찬성해 교단을 탈퇴하면 종전 교회 재산은 탈퇴한 교인들의 총유가 됩니다.","구성원은 지분권에 기하여 총유물의 보존행위를 할 수 없다(비법인사단 자체가 하여야 한다)":"총유에는 구성원 각자의 지분이 없어서 개별 구성원이 단독으로 보존행위를 하지 못하고 단체가 해야 합니다.","궁박, 경솔, 무경험은 그 중 일부만 갖추어져도 충분하다":"세 가지 약점을 모두 갖출 필요는 없고 어느 하나만 있어도 요건이 충족됩니다.","권리남용이 불법행위가 되어 생기는 손해배상청구권: 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년의 시효를 받는다. 1년 단기시효는 없다":"권리남용에 따른 배상청구권은 안 날부터 3년, 한 날부터 10년의 시효를 받고 1년 단기시효는 없습니다.","권리만을 얻거나 의무만을 면하는 행위는 미성년자가 단독으로 할 수 있다(동의 불필요)":"증여를 받는 것처럼 미성년자에게 이익만 생기는 행위는 법정대리인 동의 없이 혼자 해도 됩니다.","권리의 행사와 의무의 이행은 신의에 좇아 성실히 하여야 한다":"권리를 쓰고 의무를 이행할 때 상대의 믿음을 저버리지 않고 성실하게 해야 하는 원칙입니다.","권리자의 일방적 의사표시로 법률관계를 발생·변경·소멸시키는 권리. 취소권·추인권·동의권·해제권·해지권·상계권·상속포기권 등":"형성권은 권리자 혼자 의사표시만 해도 법률관계를 만들고 바꾸고 없애는 권리입니다.","권리행사 가능한 권리자가 오랜 기간 행사하지 않아 상대방이 더는 행사하지 않으리라 신뢰할 정당한 사유가 생긴 때 그 후의 권리행사를 막는다. 공법관계인 권력관계에도 적용될 수 있다":"오래 행사하지 않아 상대가 안 하리라 믿을 만하면 뒤늦은 권리행사를 막는 원칙이 실효입니다.","권리행사에 법률상의 장애사유가 없는 때를 말한다. 사실상의 장애(권리의 존재나 행사 가능성을 알지 못함, 채무자 무자력 등)는 포함되지 않는다":"기산의 장애는 법적인 장애를 뜻해서 권리를 모르거나 채무자가 가난한 것 같은 사실상 사정은 포함되지 않습니다.","권한을 넘은 표현대리에서 기본대리권은 권한 외 행위와 동종의 것일 필요가 없다":"권한 초과 표현대리의 바탕이 되는 기본대리권은 넘어선 행위와 같은 종류가 아니어도 됩니다.","귀속시기: 생전처분은 법인이 성립된 때, 유언은 유언의 효력이 발생한 때부터 법인에 귀속한다(법인 성립 시에 법인재산이 된다)":"출연 재산은 생전처분이면 법인 성립 때, 유언이면 유언의 효력 발생 때부터 법인에 귀속됩니다.","그 기한이 객관적으로 도래한 때부터 진행한다":"불확정기한 채권은 그 사실이 객관적으로 일어난 때부터 시효가 진행하고 채무자가 안 때가 기준이 아닙니다.","그 비용은 부재자의 재산으로 지급한다":"보존 처분에 드는 비용은 관리인이 아니라 부재자 본인의 재산에서 냅니다.","그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. 상대방이 표의자의 착오를 알고 이를 이용한 경우에는 표의자에게 중대한 과실이 있어도 취소할 수 있다":"중대한 과실로 착오했다면 취소할 수 없지만 상대가 착오를 알고 이용했다면 중대한 과실이 있어도 취소됩니다.","근로계약이 취소된 경우 이미 제공된 노무를 기초로 형성된 취소 이전의 법률관계는 소급하여 효력을 잃지 않는다":"근로계약이 취소되어도 이미 일하고 형성된 법률관계는 소급해서 없어지지 않고 그대로 유지됩니다.","급박한 곤궁. 경제적 원인뿐 아니라 심리적 원인에 기인할 수도 있다":"궁박은 돈이 없는 상황뿐 아니라 마음이 몰려 있는 심리 상태에서도 인정될 수 있습니다.","기간 경과 시부터 장래에 향하여 소멸":"제척기간은 기간이 지난 때부터 앞으로 권리가 없어지는 것이어서 소급하지 않습니다.","기간을 시·분·초로 정한 때에는 즉시로부터 기산한다":"시간 단위로 정한 기간은 날짜를 따질 것 없이 바로 그 순간부터 세기 시작합니다.","기간을 일·주·월·연으로 정한 때에는 기간 말일의 종료로 기간이 만료한다":"일 단위 이상으로 정한 기간은 마지막 날이 모두 지나가야 끝납니다.","기간을 일·주·월·연으로 정한 때에는 기간의 초일은 산입하지 아니한다(초일불산입). 그러나 그 기간이 오전 영시로부터 시작하는 때에는 초일을 산입한다":"일 단위 이상의 기간은 첫날을 빼고 세지만 오전 영시부터 시작하면 첫날도 포함해 셉니다.","기간을 주·월·연으로 정한 때에는 역(曆)에 의하여 계산한다. 주·월·연의 처음으로부터 기간을 기산하지 아니하는 때에는 최후의 주·월·연에서 그 기산일에 해당한 날의 전일로 기간이 만료한다":"주와 월과 연은 달력대로 세고 중간부터 시작한 기간은 마지막 달에서 시작한 날에 해당하는 날의 전날 끝납니다.","기간의 계산은 법령, 재판상의 처분 또는 법률행위에 다른 정한 바가 없으면 민법의 규정에 의한다":"법령이나 재판, 계약에서 따로 정하지 않았다면 기간은 민법의 기간 계산 규정으로 셉니다.","기간의 말일이 토요일 또는 공휴일에 해당한 때에는 기간은 그 익일로 만료한다. 휴일이 연속되면 연속된 휴일의 다음 날이 만료일이다. 공휴일 특칙은 기간의 말일에만 적용된다. 초일이 공휴일이라고 기산을 다음 날로 미루지 않는다":"기간의 마지막 날이 토요일이나 공휴일이면 다음 날 끝나며, 첫날이 공휴일인 경우에는 시작을 미루지 않습니다.","기망으로 법률행위 내용으로 표시되지 않은 동기에 관하여 착오를 일으킨 경우에도 사기를 이유로 취소할 수 있다":"표시되지 않은 동기를 속여 착각하게 한 경우에도 사기를 이유로 취소가 가능합니다.","기산일에 소급하여 권리 소멸(소급효)":"소멸시효는 완성되면 시효가 시작된 날로 소급해서 권리가 없었던 것으로 정리합니다.","기산점은 권리를 행사할 수 있는 때이다":"소멸시효는 권리를 실제로 행사할 수 있게 된 때부터 세기 시작합니다.","기산점은 특별한 사정이 없는 한 권리가 발생한 때이다":"제척기간은 권리를 행사할 수 있는지와 상관없이 권리가 생긴 때부터 기산합니다.","기산점을 특정 날(오는 7월 1일부터)로 정한 때에는 그 날이 초일로 산입된다. ‘6월 1일부터 4일 동안’이면 기산점은 6월 1일이다":"특정 날짜부터라고 못 박으면 그날이 곧 첫날로 포함되므로 6월 1일부터 4일이면 6월 1일부터 셉니다.","기한 도래의 효과는 당사자의 특약으로도 소급하게 할 수 없다(조건과 달리 소급효 없음)":"기한은 확실히 올 시점이라 그 효과는 특약으로도 소급시킬 수 없고 이 점이 조건과 다릅니다.","기한부 법률행위에는 제148조·제149조를 준용한다":"기한이 붙은 법률행위에도 조건부 권리의 침해 금지와 처분 규정을 가져와 적용합니다.","기한은 채무자의 이익을 위한 것으로 추정한다. 기한의 이익은 이를 포기할 수 있다. 그러나 상대방의 이익을 해하지 못한다. 상대방의 손해를 배상하고 포기할 수 있다":"기한의 이익은 채무자 몫으로 추정되어 포기할 수 있지만 상대 이익을 해치면 안 되고 손해를 배상하면 포기가 가능합니다.","기한이 도래한 때(그 다음 날)부터 진행한다":"확정기한이 있는 채권은 기한이 닥친 다음 날부터 시효가 진행합니다.","기한이익 상실 특약은 특별한 사정이 없는 한 청구 시 상실하는 형성권적 기한이익 상실 특약으로 추정한다(정지조건부 특약으로 추정하지 않는다)":"기한이익 상실 특약은 특별한 사정이 없으면 채권자가 청구할 때 잃는 형성권적 특약으로 추정합니다.","나이는 출생일을 산입하여 만(滿) 나이로 계산하고 연수로 표시한다. 1세에 이르지 아니한 경우에는 월수로 표시할 수 있다":"나이는 태어난 날을 넣어 만 나이로 세고, 한 살이 안 되면 개월 수로 나타낼 수 있습니다.","내 토지의 매매: 허가 전에는 유동적 무효이다. 허가를 받으면 소급하여 유효가 되고, 불허가 확정이나 허가를 배제·잠탈하는 내용의 계약은 확정적 무효이다":"토지거래허가구역 매매는 허가 전에는 유동적 무효이고 허가를 받으면 소급해 유효가 되며 불허가가 확정되면 무효입니다.","노역인·연예인의 임금 및 그에 공급한 물건의 대금채권":"일용직 노역인이나 연예인의 임금과 그들에게 공급한 물건 대금은 가장 짧은 단기시효에 걸립니다.","누가 기망·강박을 했는지를 묻지 않고 취소할 수 있다":"상대방이 없는 의사표시는 지킬 상대의 신뢰가 없어서 누가 속였든 따지지 않고 취소됩니다.","능력자가 된 후의 제한능력자에게 1개월 이상의 기간을 정하여 취소할 수 있는 행위의 추인 여부를 촉구한다. 그 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다":"능력자가 된 상대에게 1개월 이상 기간을 주고 추인 여부를 물어 답이 없으면 추인한 것으로 봅니다.","다른 의사표시가 없으면 계약 시에 소급하여 효력이 생긴다. 제3자의 권리를 해하지 못한다":"추인하면 별다른 의사가 없는 한 계약한 때로 거슬러 올라가 효력이 생기지만 제삼자의 권리는 건드리지 못합니다.","단독행위(취소·추인·상계·해제·유언·소유권 포기 등) / 계약 / 합동행위":"법률행위는 한 사람의 의사로 되는 단독행위, 서로 합의하는 계약, 같은 방향의 합동행위로 나뉩니다.","당사자가 임의규정과 다른 의사를 표시한 때에는 그 의사에 의한다":"임의규정은 당사자가 다르게 정하면 물러나므로 합의한 뜻이 규정이나 관습보다 앞섭니다.","당사자가 조건성취의 효력을 그 성취 전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다":"조건 성취의 효력은 원칙적으로 성취 때부터이지만 당사자가 소급하기로 정하면 그 약정이 우선합니다.","당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다":"급박한 곤궁이나 경솔, 경험 부족을 이용해 현저히 불공정하게 한 거래는 무효입니다.","당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다. 확정적 무효가 된 법률행위는 당사자의 추인으로 유효하게 할 수 없다":"강행규정을 어긴 행위는 법원이 스스로 판단하고 한번 확정적으로 무효가 되면 추인해도 되살릴 수 없습니다.","당사자의 주장·증명이 없어도 법원이 직권으로 확정할 수 있다":"관습법은 법이어서 당사자가 증명하지 않아도 법원이 스스로 존재를 판단할 수 있어요.","대리권 소멸사유 외에 원인된 법률관계의 종료에 의하여 소멸한다. 법률관계의 종료 전에 본인이 수권행위를 철회한 경우에도 같다":"임의대리권은 기초가 된 위임 관계가 끝나거나 본인이 수권행위를 철회해도 소멸합니다.","대리권 소멸 후의 표현대리가 인정되는 경우 그 표현대리의 권한을 넘은 대리행위가 있을 때에는 권한을 넘은 표현대리가 성립할 수 있다":"대리권 소멸 후의 표현대리 상태에서 그 권한마저 넘는 행위를 해도 두 규정이 겹쳐 표현대리가 성립할 수 있습니다.","대리권 없는 자가 타인의 대리인으로 한 계약은 본인이 추인하지 아니하면 본인에 대하여 효력이 없다(유동적 무효)":"무권대리 계약은 본인이 추인해야만 효력이 생기고 그때까지는 불확정한 상태에 놓인 유동적 무효입니다.","대리권은 그 권한에 부수하여 필요한 한도에서 상대방의 의사표시를 수령하는 수령대리권을 포함한다":"대리권에는 그 업무에 딸려 필요한 범위에서 상대방의 의사표시를 대신 받을 권한도 들어 있습니다.","대리권을 증명하지 못하고 본인의 추인도 받지 못한 경우 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다. 대리권 흠결에 관한 무과실책임이다(대리인의 과실이 필요 없다)":"무권대리인은 상대의 선택에 따라 계약 이행이나 손해배상을 해야 하고 과실이 없어도 책임을 집니다.","대리권의 소멸은 선의의 제3자에게 대항하지 못한다. 그러나 제3자가 과실로 그 사실을 알지 못한 때에는 그러하지 아니하다":"대리권이 없어진 것을 모르는 선의의 제삼자에게는 소멸을 주장하지 못하지만 과실이 있으면 주장할 수 있습니다.","대리인에 대한 성년후견의 개시는 대리권의 소멸사유이다. 피한정후견인·피특정후견인에 대한 후견 개시는 소멸사유가 아니다":"대리인에게 성년후견이 시작되면 대리권이 소멸하지만 한정후견이나 특정후견은 소멸 사유가 아닙니다.","대리인에 의한 계약체결의 경우 특별한 사정이 없는 한 착오의 유무는 대리인을 표준으로 판단한다":"대리인이 계약했다면 착오가 있었는지는 본인이 아닌 대리인을 기준으로 판단합니다.","대리인은 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자 쌍방을 대리하지 못한다. 그러나 채무의 이행은 할 수 있다":"본인 허락 없이 대리인이 자기와 계약하거나 양쪽을 모두 대리할 수 없고 이미 있는 채무의 이행만 가능합니다.","대리인은 행위능력자임을 요하지 아니한다. 본인은 대리인이 제한능력자라는 이유로 대리행위를 취소할 수 없다":"대리인은 행위능력자가 아니어도 되므로 본인은 대리인이 제한능력자라는 이유로 대리행위를 취소하지 못합니다.","대리인이 권한 내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 효력이 생긴다. 대리인에 대한 제3자의 의사표시에도 준용한다":"대리인이 본인을 위한 것임을 밝히고 권한 안에서 한 의사표시는 본인에게 곧바로 효력이 생깁니다.","대리인이 그 권한 외의 법률행위를 한 경우 제3자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때 본인은 책임이 있다":"대리인이 권한을 넘어 행위해도 상대가 권한이 있다고 믿을 정당한 이유가 있으면 본인이 책임집니다.","대리인이 본인을 위한 것임을 표시하지 않은 때 그 의사표시는 자기를 위한 것으로 본다. 그러나 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때에는 본인에게 효력이 있다":"본인을 위한 것이라고 밝히지 않으면 대리인 자신의 행위로 보지만 상대가 알았거나 알 수 있었다면 본인에게 효력이 있습니다.","대리인이 수인인 때에는 각자가 본인을 대리한다. 법률 또는 수권행위에 다른 정한 바가 있으면 그에 따른다":"대리인이 여럿이면 각자 단독으로 본인을 대리하며 법률이나 수권행위에서 달리 정하면 그에 따릅니다.","대리인이 제3자 또는 자기의 이익만을 위하여 대리행위를 하고 상대방이 이를 알았거나 알 수 있었을 때에는 본인에게 효과가 없다(제107조 제1항 단서 유추)":"대리인이 자기나 제삼자의 이익만 노리고 한 행위를 상대가 알았거나 알 수 있었다면 본인에게 효과가 없습니다.","대리행위가 강행법규 위반으로 무효이면 표현대리 법리가 적용되지 않는다":"행위 자체가 강행법규 위반으로 무효라면 대리권의 외관을 믿었더라도 표현대리로 구제하지 않습니다.","대리행위의 표시를 하지 않고 성명을 모용하여 자기가 본인인 것처럼 기망하여 본인 명의로 직접 법률행위를 한 경우 특별한 사정이 없는 한 권한을 넘은 표현대리는 성립하지 않는다":"대리인이라고 밝히지 않고 본인인 척 이름을 써서 한 행위는 특별한 사정이 없으면 권한 초과 표현대리가 되지 않습니다.","대표권 없는 일반 직원의 불법행위는 제35조가 아니라 사용자책임(제756조)의 문제이다":"대표권이 없는 직원이 낸 사고는 법인의 불법행위 규정이 아니라 사용자책임 규정으로 다룹니다.","대표자가 계약을 체결하고 법인의 채무불이행으로 상대방이 계약을 해제한 경우 원상회복의무는 계약 당사자인 법인이 부담한다. 대표자 개인이 부담하지 않는다":"계약의 당사자는 법인이므로 해제 후 원상회복은 법인이 하고 대표자 개인에게는 의무가 없습니다.","대표자가 대표자로서의 모든 권한을 타인에게 포괄적으로 위임하면 그 대행행위는 원칙적으로 법인에 효력이 없다(이사의 대리인 선임은 특정한 행위에 한함). 포괄 위임을 받아 실질적으로 대표자로서 사무를 집행하는 자는 사실상 대표자로서 제35조의 책임이 생길 수 있다":"대표 권한 전부를 맡기는 위임은 법인에 효력이 없고, 실질적으로 대표 역할을 한 사람은 사실상 대표자로 책임집니다.","대표자가 자기 또는 제3자의 이익을 위하여 대표권을 남용한 경우, 상대방이 그 사정을 알았거나 알 수 있었을 때에는 법인에 효력이 없다(제107조 제1항 단서 유추)":"대표자가 사익을 위해 권한을 남용한 사정을 상대가 알았거나 알 수 있었다면 법인에 효력이 없습니다.","대표자의 부정한 대표행위라도 직무범위 내에 있으면 법인의 불법행위가 성립할 수 있다":"대표자가 부정하게 행동했더라도 직무 범위 안의 일이면 법인의 불법행위로 인정될 수 있습니다.","도과 여부를 법원이 직권으로 조사한다":"제척기간이 지났는지는 당사자가 주장하지 않아도 법원이 스스로 조사해 판단합니다.","도급받은 자·기사 그 밖에 공사의 설계 또는 감독에 종사하는 자의 공사에 관한 채권":"공사를 맡은 사람이나 설계와 감독을 하는 기사의 공사 관련 채권은 단기시효에 걸립니다.","도박자금에 제공할 목적의 금전대차, 성매매 전제의 선불금 대여":"도박 자금이나 성매매를 전제로 돈을 빌려주는 계약은 사회질서에 어긋나 효력이 없습니다.","독립한 물건이면 부동산도 종물이 될 수 있다":"종물이 반드시 동산일 필요는 없고 독립한 물건이기만 하면 건물 같은 부동산도 해당합니다.","동기가 상대방에게 표시되어 의사표시의 내용이 된 경우 또는 상대방이 유발한 경우 법률행위 내용의 착오가 되어 취소할 수 있다":"동기를 상대에게 밝혀 내용이 되었거나 상대가 착오를 일으켰다면 동기의 착오도 취소 사유가 됩니다.","동시이행항변권·보증인의 최고·검색 항변권":"항변권은 상대의 청구를 거절할 수 있게 해 주는 권리로, 동시이행항변권과 보증인의 항변권이 있어요.","동의가 필요한 법률행위를 동의 없이 한 때에는 취소할 수 있다. 다만 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 법률행위는 취소할 수 없다":"동의가 필요한 행위를 혼자 하면 취소되지만 일상에 필요한 소액 거래는 예외로 취소할 수 없습니다.","동의를 요하도록 하는 규정은 강행규정이다. 법정대리인의 동의는 묵시적으로도 할 수 있다":"동의 요건은 당사자가 빼기로 합의할 수 없는 규정이며, 동의는 말 없이 행동으로도 할 수 있어요.","두 기간은 제척기간이다. 어느 하나라도 먼저 지나면 취소권은 소멸한다":"두 기간 중 하나라도 먼저 끝나면 취소권이 사라지는 제척기간으로 중단이나 정지가 없습니다.","매도인의 배임행위에 제2매수인이 적극 가담한 때 제2매매는 무효이다. 제2매수인으로부터 취득한 제3자는 선의라도 보호되지 않는다":"둘째 매수인이 배임에 적극 가담하면 둘째 매매는 무효이고 그에게서 산 제삼자는 선의라도 보호받지 못합니다.","매도인의 하자담보책임이 성립하는 경우에도 매수인은 착오를 이유로 취소할 수 있다(두 규정은 경합)":"하자담보책임과 착오 취소는 요건이 달라 매수인이 둘 중 어느 쪽이든 선택해 주장할 수 있습니다.","매도인이 매수인의 채무불이행을 이유로 매매계약을 적법하게 해제한 후에도 매수인은 착오를 이유로 매매계약을 취소할 수 있다":"해제된 뒤에도 매수인은 착오를 이유로 계약을 취소해 계약 전체를 무효로 돌릴 수 있습니다.","매매계약의 해제는 법률행위(단독행위)이다. 준법률행위가 아니다":"해제는 효과를 의사에 따라 일으키는 단독행위여서 법률이 정한 효과만 붙는 준법률행위와 다릅니다.","매매계약 체결 대리권을 수여받은 자는 특별한 사정이 없는 한 중도금·잔금을 수령할 권한이 있다. 매매계약의 체결과 이행에 대하여 포괄적인 대리권을 수여받은 자는 특별한 사정이 없는 한 약정된 매매대금의 지급기일을 연기해 줄 권한이 있다":"매매 체결을 맡은 대리인은 중도금과 잔금도 받을 수 있고, 이행까지 포괄 위임받았다면 대금 지급기일도 미뤄 줄 수 있습니다.","매매위임장을 제시하고 계약서에 대리인의 성명만 기재한 경우에도 특단의 사정이 없는 한 본인에게 효력이 있다":"위임장을 보여 주고 대리인 이름만 적었어도 특별한 사정이 없으면 본인을 위한 계약으로 효력이 인정됩니다.","매수인의 소유권이전등기청구권은 채권으로서 소멸시효에 걸린다. 그러나 매수인이 목적 부동산을 인도받아 점유·사용·수익하고 있는 동안에는 시효가 진행하지 않는다":"매수인의 등기청구권은 채권이라 시효에 걸리지만 부동산을 인도받아 쓰는 동안에는 시효가 진행하지 않습니다.","매수인이 점유를 상실한 때부터는 소유권이전등기청구권의 소멸시효가 진행한다":"매수인이 부동산을 더는 점유하지 않게 되면 그때부터 등기청구권의 시효가 다시 진행합니다.","목적, 명칭, 사무소, 설립허가의 연월일, 존립시기나 해산이유를 정한 때 그 시기·사유, 자산의 총액, 출자의 방법을 정한 때 그 방법, 이사의 성명·주소, 이사의 대표권을 제한한 때 그 제한":"설립 때 등기하는 항목으로 목적과 명칭, 자산 총액, 이사 인적사항, 대표권 제한 등을 적습니다.","목적, 명칭, 사무소의 소재지, 자산에 관한 규정, 이사의 임면에 관한 규정, 사원자격의 득실에 관한 규정, 존립시기나 해산사유를 정하는 때에는 그 시기 또는 사유":"사단법인 정관에 반드시 적어야 하는 사항들이며 존립시기와 해산사유는 정한 경우에만 적습니다.","목적달성 또는 재산보전을 위하여 적당한 때에는 정관에 변경방법이 없어도 명칭 또는 사무소의 소재지를 변경할 수 있다. 정관변경은 주무관청의 허가를 얻어야 한다":"변경 방법이 없어도 목적 달성에 필요하면 명칭과 소재지는 바꿀 수 있으며 주무관청의 허가가 필요합니다.","무권대리인이 본인을 단독상속하고 본인의 지위에서 자신이 한 무권대리행위의 추인을 거절하는 것":"자기가 한 무권대리를 본인 지위에서 추인하지 않겠다고 버티는 것은 신의칙에 반합니다.","무권대리인이 본인을 단독상속한 경우 본인의 지위에서 추인을 거절하는 것은 신의칙에 반하여 허용되지 않는다":"무권대리인이 본인의 지위를 물려받고서 자기가 한 행위를 추인하지 않는 것은 허용되지 않습니다.","무권리자가 타인의 권리를 처분하는 계약을 한 경우 권리자가 추인하면 그 계약의 효과는 원칙적으로 계약체결 시로 소급하여 권리자에게 귀속한다":"권리 없는 사람이 남의 권리를 처분했어도 권리자가 추인하면 원칙적으로 계약 때로 소급해 권리자에게 효과가 돌아갑니다.","무상행위(증여 등 대가 관계 없는 행위)는 불공정한 법률행위의 대상이 아니다. 경매에는 제104조가 적용되지 않는다":"주고받는 대가가 없는 증여 같은 행위는 불공정 판단 대상이 아니고 경매에도 이 규정이 적용되지 않습니다.","무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다":"무효인 행위가 다른 행위의 요건을 갖추고 무효를 알았다면 그것을 원했을 것으로 인정되면 그 행위로 효력을 가집니다.","무효인 법률행위는 추인하여도 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다(소급효 없음). 묵시적으로 할 수 있다":"무효는 추인해도 되살아나지 않지만 무효임을 알고 추인하면 그때부터 새 행위로 보며 소급하지 않습니다.","물건의 사용대가로 받는 금전 기타의 물건(임료·이자 등)":"법정과실은 물건을 빌려 쓰게 해 주고 받는 월세나 이자처럼 사용의 대가로 받는 돈입니다.","물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 이에 부속하게 한 때 그 부속물":"종물은 어떤 물건을 계속 쓰는 데 도움이 되도록 같은 소유자가 곁에 붙여 둔 다른 물건을 말합니다.","물건의 용법에 의하여 수취하는 산출물":"천연과실은 과일이나 새끼 동물처럼 물건을 본래 쓰임대로 사용해 얻는 산출물입니다.","미등기 무허가건물의 양수인에게는 소유권에 준하는 관습법상 물권이 인정되지 않는다":"무허가 미등기 건물을 넘겨받은 사람에게는 소유권에 견줄 관습법상 물권을 주지 않습니다.","미성년자가 법률행위를 함에는 법정대리인의 동의를 얻어야 한다. 위반한 행위는 취소할 수 있다":"미성년자가 동의 없이 한 법률행위는 일단 유효하지만 나중에 취소하면 처음부터 없던 일이 됩니다.","미성년자가 법정대리인으로부터 허락을 얻은 특정한 영업에 관하여는 성년자와 동일한 행위능력이 있다":"허락받은 특정 영업에 한해 미성년자도 어른과 똑같이 혼자 법률행위를 할 수 있습니다.","미성년자가 법정대리인의 동의 없이 한 법률행위의 취소권자: 미성년자 본인(단독으로 취소 가능), 법정대리인, 그 대리인·승계인":"취소할 수 있는 사람은 미성년자 본인과 법정대리인, 그리고 이들의 대리인이나 승계인입니다.","미성년자가 성년에 이른 날부터 3년, 법정대리인이 미성년자의 매매계약을 안 날부터 3년, 그 계약을 한 날부터 10년 중 어느 것이든 먼저 지나면 취소권을 행사할 수 없다":"성년이 된 날이나 법정대리인이 안 날부터 3년, 계약한 날부터 10년 중 먼저 끝나는 기간에 취소권이 사라집니다.","미성년자가 주민등록증을 변조하여 능력자로 믿게 한 경우 법률행위를 취소할 수 없다":"주민등록증을 위조해 성인으로 믿게 한 미성년자는 적극적 속임수를 썼으므로 취소하지 못합니다.","미성년자나 피한정후견인이 속임수로써 법정대리인의 동의가 있는 것으로 믿게 한 경우에도 취소할 수 없다":"동의가 있는 것처럼 속인 미성년자나 피한정후견인도 취소권을 잃는다는 규정이에요.","민법상 청산절차에 관한 규정은 강행규정이다. 이에 반하는 잔여재산의 처분행위는 특별한 사정이 없는 한 무효이다":"청산절차 규정은 당사자가 바꿀 수 없는 강행규정이라 이를 어긴 잔여재산 처분은 원칙적으로 무효입니다.","민법의 기간에 관한 규정은 사법관계뿐 아니라 공법관계에도 적용된다":"민법의 기간 계산 규정은 사인 사이의 관계뿐 아니라 공법상 관계에도 두루 적용됩니다.","민사에 관하여 법률에 규정이 없으면 관습법에 의하고, 관습법이 없으면 조리에 의한다 → 법원 적용 순서: 제정법 → 관습법 → 조리":"재판 기준은 법률이 먼저이고, 법률이 비면 관습법, 그것도 없으면 조리를 적용합니다.","반사회적 행위로 조성된 비자금을 소극적으로 은닉하기 위한 임치":"불법 자금을 소극적으로 숨겨 맡기는 임치는 적극 가담과 달라 반사회질서 행위로 보지 않습니다.","법률관계 당사자가 상대방의 이익을 고려하여 형평에 어긋나거나 신의를 저버리는 내용·방법으로 권리를 행사하거나 의무를 이행하여서는 안 된다는 추상적 규범이다":"상대 이익을 헤아리지 않고 형평에 어긋나게 권리를 쓰면 안 된다는 추상적인 기준이에요.","법률상 이해관계가 있는 자. 부재자의 제1순위 상속인이 있으면 제2순위 상속인은 이해관계인이 아니다":"법적으로 이해관계가 있어야 하며, 앞선 순위 상속인이 있으면 뒤 순위 상속인은 해당하지 않아요.","법률의 금지에 위반되는 행위라도 선량한 풍속 기타 사회질서에 위반하지 않으면 제746조의 불법원인에 해당하지 않는다":"법의 금지를 어겼더라도 사회질서를 위반한 것이 아니면 불법원인급여로 보지 않아 반환을 청구할 수 있어요.","법률행위가 무효와 취소사유를 모두 포함하고 있는 경우, 당사자는 취소권이 있다면 무효에 따른 효과를 제거하기 위해 이미 무효인 법률행위를 취소할 수 있다":"무효인 행위에 취소 사유도 있다면 무효의 효과를 없애기 위해 취소권을 행사할 수 있는 이중효과가 인정됩니다.","법률행위가 이루어진 때이다. 동기의 불법은 동기가 표시되거나 상대방에게 알려진 경우 문제된다":"반사회성은 행위를 한 시점을 기준으로 따지고 동기는 상대에게 표시되거나 알려진 때만 문제 삼습니다.","법률행위 당시 이미 성취한 조건이 정지조건이면 조건 없는 법률행위, 해제조건이면 그 법률행위는 무효":"계약할 때 이미 이뤄진 조건이 정지조건이면 조건 없는 행위가 되고 해제조건이면 행위가 무효입니다.","법률행위 당시 이미 성취할 수 없는 조건이 해제조건이면 조건 없는 법률행위, 정지조건이면 그 법률행위는 무효":"계약할 때 이미 이룰 수 없는 조건이 해제조건이면 조건 없는 행위가 되고 정지조건이면 행위가 무효입니다.","법률행위에 흠결이 있을 때 당사자의 가정적 의사, 임의규정, 관습, 신의칙으로 보충한다":"계약에 빈 곳이 있으면 당사자의 가상의 뜻과 임의규정, 관습, 신의칙으로 메웁니다.","법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 그러나 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다":"일부가 무효면 원칙적으로 전부 무효이지만 무효 부분 없이도 계약했을 것이라 인정되면 나머지는 유효합니다.","법률행위의 일종으로 법률효과를 발생시키는 법률요건이다":"단독행위는 한 사람의 의사표시만으로 법률효과를 일으키는 법률행위의 한 종류입니다.","법률행위의 자유(계약의 자유)는 사적 자치의 주요한 발현 형식이다":"스스로 법률관계를 정할 자유 중에서도 계약의 자유가 사적 자치를 대표적으로 드러냅니다.","법률행위의 효력이 처음부터 발생하지 않는 것. 누구든지 무효를 주장할 수 있다. 취소권자 제한(제140조)은 무효에 적용되지 않는다":"무효는 처음부터 효력이 없는 것이라 누구든 주장할 수 있고 취소처럼 주장할 사람이 제한되지 않습니다.","법률행위 효력의 발생 또는 소멸을 장래의 불확실한 사실의 성부에 의존하게 하는 부관":"조건은 앞으로 일어날지 불확실한 사실에 따라 법률행위의 효력이 생기거나 없어지게 하는 부가 약정입니다.","법률효과는 법률의 규정에 의해 발생한다":"감정의 표시는 당사자가 원하는 효과가 아니라 법이 정한 효과만 붙는 준법률행위에 속합니다.","법률효과 발생에 의사표시가 필수적인 것은 유언이다":"유언은 유언자의 의사표시가 있어야 효과가 생기는 법률행위입니다.","법원(法源)이 아니다. 법률행위 해석·의사 보충의 자료일 뿐이다":"사실인 관습은 재판의 근거가 아니라 계약의 뜻을 풀이하고 빈 곳을 메우는 자료일 뿐입니다.","법원은 선임한 재산관리인에게 부재자 재산을 보존하기 위하여 필요한 처분을 명할 수 있다":"법원은 관리인에게 부재자 재산이 줄어들지 않도록 필요한 조치를 하라고 명할 수 있습니다.","법원은 선임한 재산관리인으로 하여금 재산의 관리 및 반환에 관하여 상당한 담보를 제공하게 할 수 있고, 부재자의 재산으로 상당한 보수를 지급할 수 있다":"법원은 관리인에게 담보를 제공하게 할 수 있고, 일한 대가는 부재자 재산에서 지급합니다.","법원의 허가는 이미 한 처분행위를 사후에 추인하는 방법으로도 할 수 있다":"허가는 미리 받는 것이 보통이지만, 이미 한 처분을 나중에 법원이 추인하는 방식도 가능합니다.","법원이 선임한 재산관리인은 관리할 재산목록을 작성하여야 한다":"법원이 정한 관리인은 일을 시작하기 전에 관리할 재산의 목록부터 만들어야 합니다.","법원이 선임한 재산관리인이 제118조의 권한(보존행위, 성질을 변하지 않는 범위의 이용·개량행위)을 넘는 행위를 하려면 법원의 허가를 얻어야 한다":"보존과 이용 개량 정도를 넘는 행위를 하려면 법원이 정한 관리인도 법원의 허가를 받아야 합니다.","법인과 대표자 개인은 모두 피해자에게 책임을 진다(법인만 책임지는 것이 아니다)":"피해자는 법인뿐 아니라 가해한 대표자 개인에게도 배상을 요구할 수 있는 구조입니다.","법인과 이사의 이익이 상반하는 사항에 관하여는 이사는 대표권이 없다. 이 경우 특별대리인을 선임하여야 한다":"법인과 이사의 이익이 부딪히면 이사는 대표할 수 없어서 따로 특별대리인을 세워야 합니다.","법인과 이사의 이익이 상반하는 사항에 관하여 이사는 대표권이 없다. 이 경우 임시이사 선임 규정(제63조)에 의하여 특별대리인을 선임하여야 한다":"법인과 이사의 이익이 충돌하는 사항은 이사가 대표할 수 없어 법원이 특별대리인을 선임합니다.","법인 아닌 사단. 단체성(규약, 대표 방법, 총회 의결, 구성원 변경에도 단체 존속)을 갖춘 실체이다. 법인격은 없으나 소송상 당사자능력이 있다":"법인 등기는 없지만 규약과 대표 체계를 갖춘 단체이며, 법인격이 없어도 소송의 당사자가 될 수 있습니다.","법인에 관한 규정 중 임시이사(제63조), 권리능력(제34조), 청산인(제82조), 대표자의 불법행위책임(제35조 제1항)은 비법인사단에 유추적용된다. 제60조(대표권 제한의 등기)는 유추적용되지 않는다":"임시이사와 권리능력, 청산인, 대표자의 불법행위책임 규정은 비법인사단에도 준용되고 등기 규정만 빠집니다.","법인은 그 주된 사무소의 소재지에서 설립등기를 함으로써 성립한다":"법인은 주된 사무소가 있는 곳에서 설립등기를 하는 때 비로소 법적으로 성립합니다.","법인은 법률의 규정에 의함이 아니면 성립하지 못한다":"법인은 법에서 정한 방식으로만 만들 수 있고 당사자가 마음대로 새 법인을 만들 수 없어요.","법인은 법률의 규정에 좇아 정관으로 정한 목적의 범위 내에서 권리와 의무의 주체가 된다":"법인의 권리능력은 정관에 적힌 목적의 범위 안에서만 인정됩니다.","법인은 성립한 때 및 매년 3월 내에 재산목록을 작성하여 사무소에 비치하여야 한다. 사업연도를 정한 법인은 성립한 때 및 그 연도 말에 작성한다":"법인은 성립 때와 매년 3월 안에 재산목록을 만들어 사무소에 두어야 하고, 사업연도가 있으면 연도 말에 만듭니다.","법인은 이사 기타 대표자가 그 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있다. 이사 기타 대표자는 이로 인하여 자기의 손해배상책임을 면하지 못한다":"대표자가 직무로 남에게 입힌 손해는 법인이 배상하고, 대표자 개인의 책임도 사라지지 않습니다.","법인은 정관 또는 총회의 결의로 감사를 둘 수 있다. 재단법인·사단법인 모두 감사는 필수기관이 아니다":"감사는 두어도 되고 안 두어도 되는 임의기관이어서 재단과 사단 모두 반드시 두지는 않습니다.","법인의 권리능력은 정관으로 정한 목적의 범위 내이다. 목적 범위는 정관에 명시된 것에 한하지 않고 목적 수행에 직접·간접으로 필요한 행위를 포함하며 객관적으로 판단한다":"정관에 적힌 목적뿐 아니라 그 목적을 이루는 데 직접이나 간접으로 필요한 행위까지 객관적으로 포함합니다.","법인의 대표에 관하여는 대리에 관한 규정을 준용한다":"법인 대표의 행위는 대리 규정을 빌려 와서 법인에게 효과가 돌아가도록 처리합니다.","법인의 대표자가 매매대금을 법인을 위하여 수령한 경우에도 법적 효과는 법인에 귀속한다":"대표자가 법인을 위해 대금을 받았다면 그 효과는 대표자가 아니라 법인에게 돌아갑니다.","법인의 목적범위 외의 행위로 타인에게 손해를 가한 때에는 그 사항의 의결에 찬성하거나 그 의결을 집행한 사원·이사 및 기타 대표자가 연대하여 배상한다":"목적 밖의 행위로 손해가 나면 법인이 아니라 의결에 찬성하거나 집행한 사원과 이사가 함께 배상합니다.","법인의 재산상황 감사, 이사의 업무집행 상황 감사, 재산상황 또는 업무집행의 부정·불비를 발견한 때 총회 또는 주무관청에 보고, 그 보고를 위하여 필요한 때 총회 소집":"감사는 재산과 업무집행을 감사하고 부정을 발견하면 총회나 주무관청에 알리며 필요하면 총회를 소집합니다.","법인의 정관에 이사의 해임사유에 관한 규정이 있으면 특별한 사정이 없는 한 정관에서 정하지 아니한 사유로 이사를 해임할 수 없다":"정관에 해임 사유가 정해져 있다면 그 밖의 사유로는 원칙적으로 이사를 해임하지 못합니다.","법인의 주소는 주된 사무소의 소재지에 있는 것으로 한다":"법인은 여러 사무소가 있어도 주소를 주된 사무소 소재지 하나로 정해 둡니다.","법인의 해산 및 청산은 법원이 검사·감독한다(설립은 주무관청)":"해산과 청산 과정은 법원이 감독하고 설립 단계에서만 주무관청이 감독합니다.","법인이 목적 이외의 사업을 하거나 설립허가의 조건에 위반하거나 그 밖에 공익을 해하는 행위를 한 때 주무관청은 설립허가를 취소할 수 있다":"목적 밖의 사업이나 허가 조건 위반으로 공익을 해치면 주무관청이 설립허가를 거둘 수 있습니다.","법인이 배상하면 법인은 대표자에게 구상할 수 있다":"법인이 먼저 배상했다면 잘못한 대표자에게 그 비용을 돌려받을 수 있습니다.","법인이 채무를 완제하지 못하게 된 때 이사는 지체 없이 파산신청을 하여야 한다":"빚을 다 갚을 수 없게 되면 이사는 미루지 않고 곧바로 파산을 신청해야 합니다.","법인이 해산한 때에는 파산의 경우를 제외하고 이사가 청산인이 된다. 정관 또는 총회의 결의로 달리 정한 바가 있으면 그에 의한다":"파산이 아닌 해산이면 이사가 청산인이 되고, 정관이나 총회 결의로 따로 정하면 그에 따릅니다.","법인 책임에는 사용자책임(제756조)과 달리 선임·감독에 주의를 다하였다는 면책이 인정되지 않는다":"사용자책임과 달리 선임과 감독에 주의했다는 이유로는 법인이 책임을 벗어나지 못합니다.","법적 확신 없는 관습. 법령 중 선량한 풍속 기타 사회질서에 관계없는 규정(임의규정)과 다른 관습이 있고 당사자의 의사가 명확하지 아니한 때에 그 관습에 의한다":"법적 확신이 없는 관습은 임의규정과 다른 관습이 있고 당사자 의사가 불분명할 때만 기준이 됩니다.","법정대리권도 권한을 넘은 표현대리의 기본대리권이 된다. 제126조는 법정대리에도 적용된다":"법정대리인의 권한도 기본대리권이 될 수 있어서 권한 초과 표현대리 규정이 법정대리에도 적용됩니다.","법정대리인은 미성년자가 아직 법률행위를 하기 전에는 동의와 허락을 취소할 수 있다":"미성년자가 아직 그 행위를 하지 않았다면 법정대리인이 이미 한 동의와 허락을 거둬들일 수 있어요.","법정대리인은 언제나 자기 책임으로 복대리인을 선임할 수 있다(복임권). 부득이한 사유로 선임한 때에는 제121조 제1항의 책임(선임·감독상 책임)만 진다":"법정대리인은 마음대로 복대리인을 둘 수 있지만 책임이 무겁고 부득이하게 선임했다면 선임과 감독 책임만 집니다.","법정대리인은 영업허락을 취소 또는 제한할 수 있다. 그러나 선의의 제3자에게 대항하지 못한다":"영업허락을 거두거나 줄여도 그 사실을 모르고 거래한 제삼자에게는 효력을 주장하지 못합니다.","법정대리인의 동의 없이 신용구매계약을 체결한 미성년자가 동의 없음을 이유로 계약을 취소하는 것":"미성년자가 동의 없는 신용구매를 취소하는 것은 법이 준 보호권이어서 신의칙 위반이 아닙니다.","법정대리인이 범위를 정하여 처분을 허락한 재산은 미성년자가 임의로 처분할 수 있다":"법정대리인이 범위를 정해 허락한 재산은 미성년자가 따로 동의를 받지 않고 스스로 처분합니다.","법정대리인이 취소한 미성년자의 법률행위는 처음부터 무효인 것으로 본다":"취소되면 효력이 처음 시점으로 거슬러 올라가 그 행위는 애초에 없었던 것으로 취급됩니다.","법정해제권의 행사, 상계, 유언, 소유권의 포기":"해제권을 쓰거나 상계하고 유언하고 소유권을 버리는 것은 한 사람의 의사표시로 끝나는 단독행위입니다.","변경 청구권자: 본인, 배우자, 4촌 이내의 친족, 한정후견인, 한정후견감독인, 검사, 지방자치단체의 장":"동의 범위를 바꿔 달라는 청구는 본인과 가까운 친족, 한정후견 관련자, 검사, 지자체장이 할 수 있습니다.","변호사·변리사·공증인·공인회계사·법무사에 대한 직무상 보관한 서류의 반환을 청구하는 채권":"법률 전문직에게 맡긴 서류를 돌려 달라는 채권도 단기소멸시효 대상에 포함됩니다.","변호사·변리사·공증인·공인회계사·법무사의 직무에 관한 채권":"변호사 등 전문직이 직무를 하고 가지는 보수 채권은 단기소멸시효에 걸립니다.","보존행위(예: 소유권이전등기말소청구, 시효중단)는 법원의 허가 없이 할 수 있다":"재산 현상을 지키는 보존행위는 권한 범위 안의 일이라 허가를 받지 않고도 할 수 있습니다.","보험금 부정취득 목적의 다수 보험계약·보험사고 가장 목적의 생명보험계약":"보험금을 부정하게 타려고 여러 보험에 들거나 사고를 꾸미려는 보험계약은 반사회적으로 무효입니다.","복대리인은 그 권한 내에서 본인을 대리하며, 본인이나 제3자에 대하여 대리인과 동일한 권리의무가 있다":"복대리인은 자기 권한 범위에서 본인을 대리하고 본인이나 상대에 대하여 대리인과 같은 권리의무를 갖습니다.","복대리인은 본인의 대리인이다. 대리인의 대리인이 아니다. 복대리인은 법정대리인이 아니라 임의대리인이다":"복대리인은 대리인의 부하가 아니라 본인을 직접 대리하는 임의대리인입니다.","복대리인은 수령한 법률행위의 목적물을 대리인에게 인도할 의무가 있다":"복대리인이 거래로 받은 물건은 대리인에게 넘겨줘야 한다는 내부 관계의 의무입니다.","복대리인을 선임한 때에는 본인에 대하여 그 선임·감독에 관한 책임이 있다. 본인의 지명에 의하여 선임한 경우에는 그 부적임 또는 불성실함을 알고 본인에게 대한 통지나 그 해임을 태만한 때가 아니면 책임이 없다":"복대리인을 고른 대리인은 선임과 감독에 책임을 지고 본인이 지명한 경우엔 부적임을 알고도 통지나 해임을 게을리했을 때만 책임집니다.","복대리인을 선임해도 대리인의 대리권은 소멸하지 않는다. 대리인의 대리권이 소멸하면(사망·파산 등) 복대리권도 소멸한다":"복대리인을 두어도 대리인의 권한은 그대로이고 대리인의 대리권이 사라지면 복대리권도 따라 사라집니다.","복임권이 없는 대리인이 선임한 복대리인의 대리권도 기본대리권이 될 수 있다":"복임권 없는 대리인이 멋대로 선임한 복대리인의 권한도 기본대리권으로 인정될 수 있습니다.","본인, 배우자, 4촌 이내의 친족, 미성년후견인, 미성년후견감독인, 검사, 지방자치단체의 장":"특정후견 청구는 본인과 가까운 친족, 미성년후견 관련자, 검사, 지자체장이 할 수 있습니다.","본인, 배우자, 4촌 이내의 친족, 미성년후견인, 미성년후견감독인, 한정후견인, 한정후견감독인, 특정후견인, 특정후견감독인, 검사, 지방자치단체의 장":"본인과 가까운 친족, 다른 후견 관련자, 검사, 지자체장이 성년후견개시를 청구할 수 있습니다.","본인의 부재 중 재산관리인의 권한이 소멸한 때에도 같다":"부재 중에 관리인의 권한이 사라져 공백이 생긴 경우에도 법원이 같은 처분을 명할 수 있습니다.","본인이 그 후에 재산관리인을 정한 때에는 법원은 본인, 재산관리인, 이해관계인 또는 검사의 청구에 의하여 처분명령을 취소하여야 한다":"본인이 나중에 직접 관리인을 정하면 법원은 청구에 따라 앞서 내린 처분명령을 거둬야 합니다.","본인이 추인을 거절하면 무권대리행위는 확정적으로 무효가 되므로 그 후에는 상대방의 철회권이 문제되지 않는다":"본인이 추인을 거절하면 무권대리는 확정적으로 무효가 되어 상대가 철회할지는 더 이상 쟁점이 되지 않습니다.","부동산을 매수할 권한을 수여받은 자는 원칙적으로 그 부동산을 처분할 권한이 없다":"부동산을 사 오라고 위임받은 사람에게 그 부동산을 되파는 권한까지 있는 것은 아닙니다.","부부간 어떠한 일이 있어도 이혼하지 않겠다는 합의":"어떤 사정이 있어도 이혼하지 않겠다는 부부 합의는 혼인의 자유를 침해하여 반사회적으로 평가됩니다.","부부 중 한쪽이 다른 쪽에 대하여 가지는 권리는 혼인관계가 종료된 때부터 6개월 내에는 시효가 완성되지 아니한다":"부부 사이의 권리는 혼인관계가 끝난 때부터 6개월 동안 시효가 완성되지 않아 부부 사이의 청구를 보호합니다.","부작위를 목적으로 하는 채권의 소멸시효는 위반행위를 한 때로부터 진행한다":"하지 않기로 한 채권은 약속을 어기고 행위를 한 순간에 권리를 행사할 수 있으므로 그때 시효가 시작됩니다.","부재자가 스스로 재산처분권을 위임한 재산관리인이 재산을 처분하는 경우 생사가 분명하지 않은 때가 아니면 법원의 허가가 필요 없다":"본인이 처분권까지 맡긴 관리인은 생사가 분명한 동안에는 법원 허가 없이 재산을 처분합니다.","부재자가 재산관리인을 정한 경우에 생사가 분명하지 아니한 때에는 법원은 재산관리인, 이해관계인 또는 검사의 청구에 의하여 재산관리인을 개임할 수 있다":"본인이 정한 관리인이 있어도 생사가 불분명하면 법원이 청구에 따라 관리인을 바꿀 수 있습니다.","부재자의 사망이 확인되어도 선임결정이 취소되지 않는 한 법원이 선임한 재산관리인의 권한은 소멸하지 않는다":"부재자가 죽은 것이 밝혀져도 선임 결정이 취소되기 전까지 관리인의 권한은 그대로 남아요.","부재자의 생사가 5년간 분명하지 아니한 때 이해관계인이나 검사의 청구에 의하여 법원은 실종선고를 하여야 한다":"생사를 알 수 없는 상태가 5년 이어지면 청구를 받은 법원이 반드시 실종선고를 해야 합니다.","부재자의 생사가 분명하지 아니한 경우 부재자가 정한 재산관리인이 권한을 넘는 행위를 할 때에도 법원의 허가가 필요하다":"생사가 불분명하면 본인이 정한 관리인이라도 권한 밖의 행위에는 법원 허가가 필요합니다.","분묘에 안치된 선조의 유골은 제사주재자에게 승계된다. 피상속인이 유언으로 유골의 매장장소를 지정하더라도 제사주재자는 그에 따를 법률적 의무를 지지 않는다":"유골은 제사를 주재하는 사람이 이어받고, 망인이 유언으로 매장 장소를 정해도 법적으로 따를 의무는 없습니다.","분사무소 설치·사무소 이전·변경은 3주간(3주일) 내에 등기한다":"분사무소를 두거나 사무소를 옮기거나 변경한 때에는 3주간 안에 등기해야 합니다.","불공정 여부는 법률행위가 이루어진 시점을 기준으로 약속된 급부와 반대급부의 객관적 가치를 비교하여 판단한다":"계약한 시점에 약속된 두 급부의 객관적 가치를 견주어 불공정한지를 가립니다.","불공정한 법률행위, 강행규정 위반으로 확정적 무효인 행위, 반사회질서 행위. 반사회질서의 법률행위로서 무효인 경우 선의의 제3자에게도 대항할 수 있다":"불공정, 강행규정 위반, 반사회질서 행위는 추인해도 유효가 되지 않고 반사회질서 무효는 선의 제삼자에게도 주장됩니다.","불공정한 법률행위로 무효인 경우 추인에 의해 유효가 될 수 없다. 그 계약에 대한 부제소합의도 무효이다. 선의의 제3자에게도 대항할 수 있다":"불공정해서 무효인 계약은 추인해도 유효가 되지 않고 소송하지 않겠다는 합의도 무효이며 제삼자에게도 주장됩니다.","불공정한 법률행위에도 무효행위의 전환(제138조)이 적용될 여지가 있다":"불공정으로 무효가 된 행위도 요건이 맞으면 다른 법률행위로서 효력을 인정받는 전환의 여지가 있습니다.","불법의 원인으로 재산을 급여하거나 노무를 제공한 때에는 그 이익의 반환을 청구하지 못한다. 불법원인이 수익자에게만 있는 때는 반환을 청구할 수 있다":"불법적인 원인으로 준 것은 돌려달라고 못 하지만 불법이 받은 쪽에만 있다면 반환을 청구할 수 있습니다.","불법행위로 인한 손해배상청구권: 피해자나 그 법정대리인이 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년":"불법행위 배상청구권은 손해와 가해자를 안 날부터 3년, 불법행위가 있던 날부터 10년이 지나면 사라집니다.","불확정한 사실이 발생한 때를 이행기한으로 정한 경우 그 사실의 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다":"불확정한 사실이 생길 때를 기한으로 했다면 그 사실이 불가능해진 때에도 기한이 온 것으로 취급합니다.","비법인사단에는 대표권 제한의 등기에 관한 규정(제60조)이 적용되지 않는다":"비법인사단은 등기 제도가 없으므로 대표권 제한을 등기해야 한다는 법인 규정이 유추되지 않습니다.","비법인사단은 정관에서 대리를 금지한 사항을 포괄적으로 위임할 수 없다":"정관이 대리를 막은 사항은 비법인사단도 포괄적으로 다른 사람에게 맡길 수 없습니다.","비법인사단의 재산은 구성원의 총유이다. 총유물의 관리·처분은 사원총회의 결의에 의한다. 각 사원은 정관 기타 규약에 좇아 총유물을 사용·수익할 수 있다":"재산은 구성원 전체가 함께 가지는 총유이고, 관리와 처분은 총회 결의로, 사용과 수익은 규약대로 합니다.","비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물의 관리·처분행위가 아니다":"남의 금전채무를 보증하는 것은 총유물 자체의 관리나 처분이 아니라서 총회 결의 대상이 아닙니다.","비진의표시는 표시와 진의의 불일치를 표의자가 알고 있다는 점에서 착오와 구별된다":"비진의표시는 표시와 속마음이 다른 것을 본인이 알고 있다는 점에서 모르고 틀리는 착오와 다릅니다.","사기·강박에 의한 의사표시의 취소는 선의의 제3자에게 대항하지 못한다. 제3자의 선의는 추정된다":"사기로 취소해도 사정을 모르는 제삼자에게는 맞서지 못하며 제삼자는 선의로 추정됩니다.","사기나 강박에 의한 의사표시는 취소할 수 있다":"속임을 당하거나 협박을 받아 한 의사표시는 자유로운 판단이 아니므로 나중에 취소할 수 있습니다.","사기로 인한 부동산 소유권을 취득한 자로부터 새로 취득한 제3자는 특별한 사정이 없는 한 선의로 추정된다":"사기로 소유권을 얻은 사람에게서 다시 산 제삼자는 특별한 사정이 없으면 선의로 추정됩니다.","사기에 의한 의사표시에는 의사와 표시의 불일치가 없다. 의사표시의 동기에 착오가 있는 것에 불과하다":"사기당한 사람의 속마음과 표시는 일치하고 단지 그렇게 하게 된 동기에 착오가 있었을 뿐입니다.","사단법인과 어느 사원과의 관계사항을 의결하는 경우 그 사원은 결의권이 없다":"법인과 특정 사원의 이해가 걸린 안건에서는 그 사원이 자기 일을 스스로 의결하지 못합니다.","사단법인은 사원명부를 비치하고 사원의 변경이 있으면 기재한다":"사단법인은 구성원이 누구인지 사원명부로 관리하고 사원이 바뀌면 바로 고쳐 적어야 해요.","사단법인은 총사원 4분의 3 이상의 동의가 없으면 해산을 결의하지 못한다. 정관에 다른 규정이 있으면 그에 의한다":"총회가 해산을 결의하려면 총사원 4분의 3 이상의 동의가 있어야 하고 정관으로 달리 정할 수 있어요.","사단법인의 사무는 정관으로 이사 또는 다른 임원에게 위임한 사항 외에는 총회의 결의에 의하여야 한다":"사단법인의 일은 정관으로 맡긴 것 외에는 구성원이 모인 총회에서 의결로 정합니다.","사단법인의 사원의 지위는 양도 또는 상속할 수 없다. 다만 정관에 정함이 있으면 상속될 수 있다는 것이 판례이다":"사원의 지위는 원칙적으로 넘기거나 상속할 수 없고, 정관에 정하면 상속이 가능하다고 판례는 봅니다.","사람은 19세로 성년에 이르게 된다":"만 나이로 19세가 되면 성년이 되어 행위능력이 완전해집니다.","사람은 생존한 동안 권리와 의무의 주체가 된다":"권리능력은 사람이 살아 있는 동안 권리를 갖고 의무를 지는 자격이라는 말입니다.","사원권의 상속 여부 등은 정관에 정한 바에 따른다. 법인의 사원권 양도·상속 금지 규정(제56조)은 정관에서 달리 정할 수 있다":"비법인사단에서 사원권을 상속할 수 있는지는 정관으로 정하며 법인의 금지 규정은 정관으로 달리 정할 수 있습니다.","사원이 없게 된 때, 총회의 결의":"사단법인에만 있는 추가 해산 사유로 구성원이 모두 없어지거나 총회에서 해산을 결의한 경우입니다.","사유 발생 시 전액 진행한다":"정지조건형 특약이면 정해 둔 사유가 생기는 순간 전액의 기한이익이 없어져 전액의 시효가 진행합니다.","사인증여는 단독행위가 아니라 계약이다":"사인증여는 증여자와 받는 사람이 합의해야 성립하므로 단독행위가 아니라 계약에 해당합니다.","사정: 계약의 기초가 된 객관적 사정. 일방 당사자의 주관적·개인적 사정은 아니다":"계약의 바탕이 된 객관적 사정만 사정변경으로 쳐 주고 한쪽의 개인적 사정은 빠집니다.","사정변경의 원칙, 실효의 원칙, 모순행위 금지(금반언), 권리남용 금지":"신의칙에서 갈라져 나온 하위 원칙으로 사정변경, 실효, 금반언, 권리남용 금지가 있습니다.","사회의 법적 확신(법적 구속력에 대한 확신)을 얻은 관습. 법률의 보충적 효력이 있다":"사람들이 법처럼 지켜야 한다고 믿게 된 관습이 관습법이며, 법률이 비어 있을 때 보충합니다.","살인을 조건으로 한 증여, 살인을 포기할 것을 조건으로 한 증여":"살인을 하면 주겠다는 약정은 물론 살인을 안 하는 대가로 주겠다는 약정도 반사회적으로 무효입니다.","상계(제493조 제1항), 취소·추인·해제·해지 등 단독행위로서 상대방의 지위를 불안하게 하는 행위, 혼인·입양 등 신분행위":"상계나 취소, 해제처럼 상대 지위를 불안하게 하는 단독행위와 혼인 같은 신분행위에는 조건을 붙이지 못합니다.","상대방과 통정한 허위의 의사표시는 무효로 한다. 이 무효는 선의의 제3자에게 대항하지 못한다":"상대와 짜고 한 거짓 의사표시는 무효이지만 사정을 모르는 제삼자에게는 무효를 내세우지 못합니다.","상대방은 상당한 기간을 정하여 본인에게 추인 여부의 확답을 최고할 수 있다. 본인이 그 기간 내에 확답을 발하지 아니하면 추인을 거절한 것으로 본다. 최고권은 계약 당시 무권대리임을 알았던 상대방도 행사할 수 있다":"상대는 본인에게 추인 여부를 물을 수 있고 답이 없으면 거절로 간주되며 무권대리임을 알았던 상대도 물을 수 있습니다.","상대방의 대리인은 제3자 사기에서의 제3자가 아니다. 상대방과 동일시하여 상대방 자신의 사기로 본다":"상대방의 대리인이 속였다면 상대방 본인이 속인 것과 같게 보아 제삼자의 사기가 아닙니다.","상대방이 기망하였으나 표의자가 기망되지 않고 의사표시를 하였다면 기망을 이유로 취소할 수 없다(인과관계 필요)":"속이려 했어도 표의자가 속지 않았다면 속임과 의사표시 사이에 인과관계가 없어 취소할 수 없습니다.","상대방이 대리권 없음을 알았거나 알 수 있었을 때, 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때":"상대가 무권대리임을 알았거나 알 수 있었거나 대리인이 제한능력자였다면 무권대리인의 책임이 없습니다.","상대방이 사용자책임을 져야 하는 관계의 피용자는 제3자에 해당한다":"상대방이 사용자책임을 지는 관계의 피용자는 상대방과 별개의 사람이므로 제삼자에 해당합니다.","상대방이 의사표시를 알 수 있는 객관적 상태에 놓인 것을 말한다. 상대방이 실제로 읽었는지는 묻지 않는다":"도달은 상대가 알 수 있는 상태에 놓였다는 뜻이라 실제로 읽었는지는 따지지 않습니다.","상대방이 이미 알고 있는 사실에 대해서는 고지의무가 없다":"상대가 이미 아는 사실은 알려 줄 필요가 없어서 침묵해도 기망이 되지 않습니다.","상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다":"상대가 있는 의사표시는 보낸 때가 아니라 상대에게 닿은 때 효력이 생깁니다.","상대방이 출석하지 아니하거나 화해가 성립되지 아니한 때에는 1월 내에 소를 제기하지 아니하면 시효중단의 효력이 없다. 임의출석의 경우에 화해가 성립되지 아니한 때에도 같다":"화해가 불발되면 1월 안에 소송을 내야 중단 효력이 유지되고 임의출석 후 화해가 안 된 경우도 같습니다.","상대방이 표의자의 진의 아님을 알았거나 이를 알 수 있었을 경우에는 무효이다. 이 무효는 선의의 제3자에게 대항하지 못한다":"상대가 진심이 아닌 줄 알았거나 알 수 있었다면 무효이지만 사정을 모르는 제삼자에게는 주장하지 못합니다.","상대방이 합리적으로 이해한 의미(표시의 객관적 의미)에 따른다":"규범적 해석은 말한 사람의 속마음이 아니라 상대가 합리적으로 이해한 객관적 의미를 따릅니다.","상대방 있는 의사표시에 관하여 제3자가 사기나 강박을 행한 경우에는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 취소할 수 있다":"제삼자가 속였을 때는 계약 상대방이 그 사실을 알았거나 알 수 있었던 경우에만 취소할 수 있습니다.","상속은 법률의 규정에 의하여 효과가 발생하며 의사표시가 필수적이지 않다":"상속은 사망으로 법이 정한 대로 효과가 생기므로 당사자의 의사표시가 필요하지 않습니다.","상속재산에 속한 권리나 상속재산에 대한 권리는 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때부터 6개월 내에는 시효가 완성되지 아니한다":"상속재산에 관한 권리는 상속인이 확정되거나 관리인이 선임되거나 파산선고가 있는 때부터 6개월은 시효가 끝나지 않습니다.","상행위로 생긴 채권의 소멸시효는 다른 법령에 단기시효가 없으면 5년이다":"상행위에서 생긴 채권은 더 짧은 시효를 정한 법령이 없다면 5년 지나 소멸합니다.","생산자 및 상인이 판매한 생산물 및 상품의 대가":"생산자나 상인이 팔고 아직 받지 못한 물건 값 채권은 단기시효로 소멸합니다.","생전처분으로 재단법인을 설립하는 때에는 증여에 관한 규정을, 유언으로 설립하는 때에는 유증에 관한 규정을 준용한다":"살아 있을 때 만드는 재단은 증여 규정을, 유언으로 만드는 재단은 유증 규정을 따릅니다.","생활의 근거되는 곳. 주소는 동시에 두 곳 이상 있을 수 있다":"주소는 생활의 중심이 되는 곳이며 한 사람에게 여러 곳이 동시에 있을 수도 있습니다.","선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다. 절대적 무효이므로 무효를 선의의 제3자에게도 대항할 수 있다":"사회질서에 반하는 행위는 절대적 무효라서 사정을 모르는 제삼자에게도 무효를 주장할 수 있습니다.","선택권을 행사할 수 있는 때부터 진행한다":"선택채권은 선택을 해야 이행할 수 있으니 선택권을 행사할 수 있는 때부터 시효가 진행합니다.","설립등기 이외의 등기사항은 등기 후가 아니면 제3자에게 대항하지 못한다. 등기한 사항은 법원이 지체 없이 공고한다":"설립등기 외의 사항은 등기를 해야 제삼자에게 효력을 주장할 수 있고 법원이 곧바로 공고합니다.","설립자가 명칭, 사무소 소재지 또는 이사 임면의 방법을 정하지 아니하고 사망한 때 이해관계인 또는 검사의 청구에 의하여 법원이 이를 정한다":"설립자가 정관의 빈칸을 남기고 죽으면 이해관계인이나 검사의 청구로 법원이 대신 정합니다.","설립자는 일정한 재산을 출연하고 제40조 제1호부터 제5호의 사항을 기재한 정관을 작성하여 기명날인하여야 한다":"재단법인 설립자는 재산을 내놓고 필수 사항을 적은 정관에 서명이나 날인을 해야 합니다.","설립허가가 있으면 3주간 내에 주된 사무소 소재지에서 설립등기를 하여야 한다":"허가를 받은 뒤 3주간 안에 주된 사무소 소재지에서 설립등기를 마쳐야 합니다.","성년후견·특정후견 중 한정후견개시 심판을 하면 종전 성년후견·특정후견의 종료 심판을 한다":"성년이나 특정후견 중에 한정후견을 시작하면 앞선 후견은 종료 심판으로 정리됩니다.","세무사의 직무에 관한 채권은 제163조에 열거된 3년의 단기소멸시효 대상이 아니다":"세무사는 열거된 직업에 들어 있지 않아 그 보수 채권은 3년 단기시효가 아니라 일반 규정을 따릅니다.","소멸시효기간이 몇 년인지는 법률 문제이므로 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다":"시효기간이 몇 년인지는 사실이 아니라 법률 문제라서 당사자가 말하지 않아도 법원이 스스로 판단합니다.","소멸시효는 권리를 행사할 수 있는 때로부터 진행한다":"시효는 법적으로 권리를 행사할 수 있게 된 때부터 흘러가기 시작한다는 일반 원칙입니다.","소멸시효는 그 기산일에 소급하여 효력이 생긴다":"시효가 완성되면 처음 시효가 시작된 날로 거슬러 올라가 권리가 사라진 것으로 봅니다.","소멸시효는 법률행위에 의하여 이를 배제, 연장 또는 가중할 수 없으나 이를 단축 또는 경감할 수 있다":"시효를 늘리거나 없애는 약정은 채무자에게 불리해서 안 되지만 줄이거나 가볍게 하는 약정은 가능합니다.","소멸시효 완성 후 채무자의 시효 원용(항변권 행사)에도 신의칙이 적용된다. 채권자의 권리행사를 불가능하게 하는 등 특별한 사정이 있으면 원용은 권리남용이 된다":"채권자가 권리를 못 쓰게 막은 사정이 있으면 채무자가 시효를 내세우는 것은 권리남용이 됩니다.","소멸시효의 기간만료 전 6개월 내에 제한능력자에게 법정대리인이 없는 경우 그가 능력자가 되거나 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 아니한다":"기간 만료 직전 6개월 안에 제한능력자에게 법정대리인이 없으면 능력자가 되거나 대리인이 취임한 때부터 6개월은 시효가 끝나지 않습니다.","소멸시효의 이익은 미리 포기하지 못한다":"시효가 완성되기 전에는 채권자가 채무자에게 시효 이익을 포기하게 강요할 수 없도록 미리 포기를 막습니다.","소멸시효의 중단사유: ① 청구 ② 압류 또는 가압류, 가처분 ③ 승인":"시효를 끊어 처음부터 다시 세게 하는 사유는 청구, 압류나 가압류와 가처분, 승인 세 가지입니다.","소송에서 사실대로 증언하는 대가로 통상 허용되는 한도를 넘는 거액을 받기로 한 약정":"사실대로 증언하는 대가라도 허용되는 한도를 넘는 거액을 받기로 하면 무효가 됩니다.","소송의 각하·기각 또는 취하의 경우에는 시효중단의 효력이 없다. 그러나 6월 내에 재판상의 청구, 파산절차참가, 압류 또는 가압류, 가처분을 한 때에는 시효는 최초의 재판상 청구로 인하여 중단된 것으로 본다":"소송이 각하되거나 취하되면 중단 효력이 없지만 6월 안에 다시 청구하는 등의 조치를 하면 처음 청구 때 중단된 것으로 봅니다.","소송행위는 강박을 이유로 민법의 취소규정에 의해 취소할 수 없다":"소송행위는 절차의 안정이 중요해서 협박을 받았더라도 민법의 취소 규정으로 취소하지 못합니다.","소유권과 점유권은 소멸시효에 걸리지 않는다. 소유권에 기한 물권적 청구권도 소멸시효에 걸리지 않는다":"소유권과 점유권은 오래 쓰지 않아도 시효로 없어지지 않고 소유권에 따른 물권적 청구권도 마찬가지입니다.","소유권에 기한 말소등기청구권(물권적 청구권)은 소멸시효에 걸리지 않는다. 계약이 취소되어 매도인이 매수인에게 소유권에 기하여 말소등기를 청구하는 경우도 같다":"소유권에서 나오는 말소등기청구권은 시효에 걸리지 않고 계약이 취소되어 매도인이 청구하는 경우도 같습니다.","속임수를 썼다는 사실의 증명책임은 취소권 배제를 주장하는 상대방에게 있다":"취소를 막으려는 상대방이 제한능력자가 속임수를 썼다는 사실을 직접 증명해야 합니다.","속임수에 해당하는지는 적극적 기망수단이 있어야 한다. 단순히 자기를 능력자라고 말한 것만으로는 속임수가 아니다":"속임수가 되려면 적극적으로 속이는 수단이 있어야 해서 능력자라고 말만 한 것은 해당하지 않습니다.","수공업자 및 제조자의 업무에 관한 채권":"수공업자나 제조업자가 일을 하고 가지는 채권은 단기소멸시효의 대상입니다.","수권행위는 묵시적인 의사표시로 할 수 있고, 사실상의 용태에 의하여 대리권의 수여가 추단될 수 있다":"대리권을 준다는 말을 하지 않아도 묵시적 의사나 행동으로 대리권 수여가 추단될 수 있습니다.","수사기관·법정에서 허위 진술의 대가로 금품을 주기로 한 약정":"수사기관이나 법정에서 거짓으로 말해 주는 대가로 돈을 주기로 한 약정은 반사회적이라 무효입니다.","수취할 권리의 존속기간일수의 비율로 취득한다(제102조)":"법정과실은 수취권리의 존속기간 일수에 비례해 취득합니다.","승소 확정판결을 받은 채권자가 시효중단을 위해 후소를 제기하는 경우, 재판상 청구가 있다는 점에 대하여만 확인을 구하는 새로운 방식의 확인소송이 허용된다":"이미 승소한 채권자가 시효 중단을 위해 후소를 낼 때 재판상 청구가 있었다는 점만 확인받는 소송이 허용됩니다.","시기 있는 법률행위는 기한이 도래한 때로부터 효력이 생긴다. 종기 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다":"시기는 정한 때가 되어야 효력이 시작되고 종기는 정한 때가 되면 효력이 끝나는 기한입니다.","시효를 원용할 수 있는 자는 권리의 소멸에 의하여 직접 이익을 받는 사람에 한정된다":"시효를 내세울 수 있는 사람은 권리가 소멸되어 직접 이익을 얻는 사람으로 한정됩니다.","시효완성의 주장은 시효의 이익을 받는 자가 하여야 한다. 당사자가 시효완성의 항변을 하지 않으면 법원은 그 의사에 반하여 재판할 수 없다(변론주의)":"시효 완성은 이익을 받는 사람이 직접 주장해야 하고 주장하지 않으면 법원이 스스로 시효를 적용할 수 없습니다.","시효완성 전에 한 채무의 일부변제는 특별한 사정이 없는 한 채무 승인으로서 시효중단사유가 될 수 있다":"시효가 끝나기 전에 빚의 일부를 갚으면 특별한 사정이 없는 한 채무를 인정한 것으로 보아 시효가 중단됩니다.","시효 완성 후 시효이익의 포기는 가능하다. 포기하면 포기한 때부터 그 채권의 소멸시효가 새로 진행한다":"시효가 끝난 뒤에는 이익을 포기할 수 있고, 포기하면 그때부터 채권의 시효가 새로 시작됩니다.","시효완성 후 채무자가 채무의 일부를 변제하면 시효이익의 포기로 본다":"시효가 끝난 뒤 채무자가 빚의 일부라도 갚으면 시효 이익을 포기한 것으로 취급합니다.","시효의 이익을 받은 자에 대하여 하지 아니한 때에는 이를 그에게 통지한 후가 아니면 시효중단의 효력이 없다":"압류 등을 시효 이익을 받을 사람에게 하지 않았다면 그에게 통지한 뒤에야 시효중단의 효력이 생깁니다.","시효이익을 받은 자가 원용하여야 한다(변론주의)":"소멸시효는 이익을 받는 사람이 직접 내세워야 효력이 생기는 변론주의에 따릅니다.","시효이익을 받을 본인의 대리인은 소멸시효 중단사유인 채무의 승인을 할 수 있다":"채무자의 대리인도 대리 권한 안에서 채무를 승인할 수 있고 그 승인은 본인의 시효를 중단시킵니다.","시효중단의 효력은 당사자 및 그 승계인 사이에만 있다":"시효중단은 상대적이라서 중단 절차를 밟은 당사자와 그 승계인 사이에서만 효력이 있습니다.","시효중단의 효력 있는 승인에는 상대방의 권리에 관한 처분의 능력이나 권한 있음을 요하지 아니한다":"채무자가 빚을 인정하는 승인은 상대 권리를 처분할 능력이나 권한이 없어도 시효중단 효과를 냅니다.","시효취득한 분묘기지권자: 토지소유자가 분묘기지에 관한 지료를 청구한 날부터의 지료를 지급한다":"시효로 분묘기지권을 얻어도 땅 주인이 지료를 청구한 날부터는 지료를 내야 합니다.","신의칙 위반은 강행규정 위반이므로 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다":"신의칙은 강행규정이라 당사자가 내세우지 않아도 법원이 스스로 위반 여부를 따질 수 있습니다.","실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다. 간주이므로 실종선고가 취소되지 않는 한 반증을 들어 다툴 수 없다":"실종선고는 사망을 간주하는 효과라서 선고가 취소되기 전에는 살아 있다는 증거로도 다툴 수 없습니다.","실종선고를 직접원인으로 재산을 취득한 자가 선의면 받은 이익이 현존하는 한도에서, 악의면 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상한다":"선고로 재산을 얻은 사람은 선의면 남은 이익만, 악의면 이자까지 붙여 돌려주고 손해도 배상합니다.","실종선고 후 취소 전에 선의로 한 행위의 효력에는 영향이 없다":"선고가 있고 취소되기 전에 사정을 모르고 한 행위는 나중에 취소돼도 그대로 효력이 유지됩니다.","실종자의 생존한 사실 또는 실종기간 만료 시와 다른 때에 사망한 사실의 증명이 있으면 법원은 본인, 이해관계인 또는 검사의 청구에 의하여 실종선고를 취소하여야 한다":"실종자가 살아 있거나 다른 때 죽었음이 증명되면 청구에 따라 법원은 선고를 취소해야 합니다.","아직 능력자가 되지 못한 경우에는 법정대리인에게 촉구하고, 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다":"아직 제한능력자라면 법정대리인에게 물어야 하고, 기간 안에 답이 없으면 추인으로 간주됩니다.","압류, 가압류 및 가처분은 권리자의 청구에 의하여 또는 법률의 규정에 따르지 아니함으로 인하여 취소된 때에는 시효중단의 효력이 없다":"압류나 가압류, 가처분이 권리자 요청이나 법 규정 위반으로 취소되면 시효중단 효력이 사라집니다.","어느 특정 영역에서의 경험부족이 아니라 거래일반에 대한 경험부족":"무경험은 한 분야를 몰랐다는 뜻이 아니라 거래 전반에 경험이 부족한 상태를 말합니다.","어느 행위에 대해 가주소를 정한 때에는 그 행위에 관하여는 가주소를 주소로 본다":"특정 행위에 쓰려고 정한 가주소는 그 행위에 한해 진짜 주소 대신 사용됩니다.","여관·음식점·대석·오락장의 숙박료·음식료·대석료·입장료·소비물의 대가 및 체당금의 채권":"여관과 음식점 요금 같은 일상적 소액 채권은 가장 짧은 단기소멸시효에 걸립니다.","여행계약에서 여행자의 안전을 확보하기 위한 합리적 조치를 할 안전배려의무가 있다":"기획여행업자는 여행 중 손님의 안전을 지키려고 합리적인 조치를 해야 합니다.","영리를 목적으로 하는 사단은 상사회사 설립의 조건에 좇아 법인으로 할 수 있고, 상사회사에 관한 규정을 준용한다":"영리를 위한 사단은 민법상 허가 대신 상법의 회사 설립 요건을 갖추어 법인이 됩니다.","영업이 허락된 범위에서는 법정대리인의 대리권이 없다. 그 영업에 관한 법정대리인의 대리행위는 유효하지 않다":"허락된 영업의 범위에서는 미성년자가 스스로 하므로 법정대리인이 대신 한 행위는 효력이 없습니다.","원물로부터 분리하는 때에 이를 수취할 권리자에게 속한다":"천연과실은 원물에서 떨어지는 순간 그 과실을 받을 권리가 있는 사람의 것이 됩니다.","원본채권이 양도되더라도 이미 변제기에 도달한 지분적 이자채권은 특별한 사정이 없는 한 당연히 함께 양도되지 않는다":"원금 채권을 넘겨도 이미 갚을 때가 된 이자 채권은 따로 약정이 없으면 같이 넘어가지 않습니다.","원칙적으로 유효이다(예외적으로 상대방 악의·과실 시 무효)":"비진의표시는 원칙적으로 유효이고, 상대가 진의가 아님을 알았거나 알 수 있었던 예외에서만 무효입니다.","월 또는 연으로 정한 경우에 최종의 월에 해당일이 없는 때에는 그 월의 말일로 기간이 만료한다":"월이나 연 단위의 끝 달에 같은 날짜가 없으면 그 달의 마지막 날에 기간이 끝납니다.","유권대리 주장 속에는 표현대리의 주장이 포함되어 있지 않다. 표현대리는 별도로 주장하여야 한다":"정당한 대리권이 있었다는 주장만으로는 표현대리 주장이 되지 않아 따로 내세워야 합니다.","유실물에 대한 소유권 취득, 점유취득시효 완성에 의한 소유권 취득은 원시취득이다":"유실물 습득과 점유취득시효로 얻는 소유권은 앞사람의 권리에 기대지 않으므로 원시취득이에요.","유체물 및 전기 기타 관리할 수 있는 자연력":"물건은 눈에 보이는 유체물과 전기처럼 사람이 지배할 수 있는 자연력까지 포함하는 개념입니다.","유효하게 성립한 계약에 따른 급부의 이행을 청구하는 경우, 법원이 신의칙으로 급부의 일부를 감축하는 것은 원칙적으로 허용되지 않는다":"계약이 유효하면 법원이 신의칙을 앞세워 급부를 줄여 줄 수는 없는 것이 원칙입니다.","의복·침구·장구 그 밖에 동산의 사용료의 채권":"옷이나 침구 같은 동산을 빌려주고 받을 사용료 채권은 가장 짧은 단기시효 대상입니다.","의사결정의 자유가 완전히 박탈된 상태의 의사표시(절대적 폭력)는 취소가 아니라 무효이다":"선택의 자유가 전혀 없을 만큼 폭력을 당한 의사표시는 취소가 아니라 처음부터 무효입니다.","의사무능력을 이유로 계약이 무효가 된 경우 의사무능력자는 선의·악의를 불문하고 받은 이익이 현존하는 한도에서 반환할 책임이 있다":"의사무능력으로 계약이 무효여도 받은 이익이 남아 있는 만큼만 돌려주면 됩니다.","의사무능력을 이유로 무효인 경우 의사무능력자는 받은 이익이 현존하는 한도에서 반환한다":"의사무능력으로 계약이 무효라도 무능력자는 받은 이익이 남은 만큼만 돌려주면 됩니다.","의사무능력자의 법률행위는 무효이다":"판단 능력이 아예 없는 상태에서 한 법률행위는 취소할 필요 없이 처음부터 효력이 없습니다.","의사무능력자 쪽(특별대리인 포함)이 의사무능력을 이유로 계약의 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다":"의사무능력자 쪽이 무효를 주장하는 것은 법이 보호하려는 바이므로 신의칙에 어긋나지 않습니다.","의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우 그 사실의 유무는 대리인을 표준으로 결정한다":"의사 흠결이나 사기, 알고 모름이 문제될 때는 의사표시를 직접 한 대리인을 기준으로 따집니다.","의사·조산사·간호사·약사의 치료·근로·조제에 관한 채권":"의사나 약사가 치료와 조제로 가지는 대금 채권은 일반 채권보다 짧은 단기시효를 받습니다.","의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다":"계약 내용의 중요한 부분에서 착각했다면 그 의사표시를 나중에 취소할 수 있습니다.","의사표시는 표의자가 진의 아님을 알고 한 것이라도 그 효력이 있다(원칙적 유효)":"속마음과 다른 말을 했더라도 일단 유효하다는 것이 비진의표시의 원칙입니다.","의사표시의 상대방이 의사표시를 받은 때에 제한능력자이면 의사표시자는 그 의사표시로써 대항할 수 없다. 다만 상대방의 법정대리인이 도달 사실을 안 후에는 대항할 수 있다":"받는 사람이 제한능력자일 때는 효력을 주장하지 못하고 법정대리인이 도달을 안 뒤에야 주장할 수 있습니다.","의사표시자가 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향이 없다":"의사표시를 보낸 뒤 보낸 사람이 죽거나 제한능력자가 되어도 이미 발송된 의사표시는 그대로 유효합니다.","이사, 임시이사, 특별대리인, 직무대행자, 청산인, 그리고 법인을 사실상 대표하여 사무를 집행하는 자(대표자로 등기되었는지는 묻지 않는다)":"법인을 대표하는 지위의 사람 모두가 대표자이며 등기 여부는 따지지 않고 실제 역할로 판단합니다.","이사가 없거나 결원이 있는 경우에 이로 인하여 손해가 생길 염려가 있는 때 법원은 이해관계인이나 검사의 청구에 의하여 임시이사를 선임하여야 한다":"이사가 없어 손해가 생길 우려가 있으면 청구를 받은 법원이 임시이사를 선임해야 합니다.","이사가 재직 중 채무액·변제기가 특정된 회사채무를 보증한 뒤 사임해도 그 보증계약을 일방적으로 해지할 수 없다":"이사가 퇴임했다는 사정만으로는 이미 특정된 회사 채무의 보증계약을 일방적으로 끊지 못합니다.","이사는 매년 1회 이상 소집하여야 한다":"통상총회는 정기적으로 열려야 하는 모임이라 이사가 해마다 한 번 이상 소집해야 합니다.","이사는 법인의 사무를 집행한다. 이사가 수인인 경우 정관에 다른 규정이 없으면 법인의 사무집행은 이사의 과반수로써 결정한다":"이사가 여러 명이면 정관에 다른 규정이 없는 한 이사 과반수의 찬성으로 사무 집행을 정합니다.","이사는 법인의 사무에 관하여 각자 법인을 대표한다. 그러나 정관의 취지에 위반할 수 없고 특히 사단법인은 총회의 의결에 의하여야 한다":"이사는 각자 법인을 대표하지만 정관에 어긋날 수 없고 사단법인은 총회 의결을 따라야 합니다.","이사는 법인의 사무에 관하여 각자 법인을 대표한다. 정관의 취지에 위반할 수 없고 특히 사단법인은 총회의 의결에 의하여야 한다":"각 이사가 단독으로 법인을 대표하지만 정관의 취지와 총회 의결의 테두리 안에서만 움직입니다.","이사는 선량한 관리자의 주의로 그 직무를 행하여야 한다. 이사가 임무를 해태한 때에는 그 이사는 법인에 대하여 연대하여 손해배상의 책임이 있다":"이사는 선량한 관리자의 주의로 일해야 하고, 게을리해 법인에 손해를 주면 함께 배상합니다.","이사는 정관 또는 총회의 결의로 금지하지 아니한 사항에 한하여 타인으로 하여금 특정한 행위를 대리하게 할 수 있다(포괄적 위임은 허용되지 않는다)":"금지되지 않은 특정 행위는 다른 사람에게 대리시킬 수 있지만 대표 권한 전부를 맡기지는 못합니다.","이사는 필요하다고 인정한 때 소집할 수 있다. 총사원의 5분의 1 이상이 회의의 목적사항을 제시하여 청구하면 이사는 소집하여야 한다(정수는 정관으로 증감 가능)":"이사는 필요하면 임시총회를 열 수 있고, 총사원 5분의 1 이상이 청구하면 반드시 소집해야 합니다.","이사 등의 과태료(500만원 이하): 등기 해태, 재산목록·사원명부 부정기재, 검사·감독 방해, 사실 아닌 신고, 제76조·제90조 위반, 파산신청 해태, 공고 해태·부정공고":"등기를 미루거나 장부를 거짓으로 쓰고 감독을 방해하는 이사 등은 500만원 이하 과태료를 냅니다.","이사의 대표권에 대한 제한은 정관에 기재하여야 효력이 있고, 등기하지 아니하면 제3자에게 대항하지 못한다(제3자의 선의·악의 불문)":"대표권 제한은 정관에 적어야 하고 등기하지 않으면 제삼자가 알았더라도 그에게 맞서지 못합니다.","이사의 대표권에 대한 제한은 정관에 기재하지 아니하면 그 효력이 없고 등기하지 아니하면 제3자에게 대항하지 못한다. 제3자는 선의·악의를 불문한다":"이사의 대표권 제한은 정관에 적어야 효력이 있고, 등기하지 않으면 제삼자가 알았어도 맞서지 못합니다.","이사의 사임은 법인의 대표기관에 대한 일방적 의사표시로 효력이 생기며 주무관청의 승인이 필요 없다":"이사는 법인 대표기관에게 사임 의사를 알리기만 하면 되고 주무관청의 승인을 받을 필요가 없어요.","이사의 직무집행을 정지하거나 직무대행자를 선임하는 가처분을 하거나 변경·취소하는 경우 주사무소 소재지 등기소에서 등기한다":"이사의 직무를 멈추거나 대행자를 두는 가처분은 법인이 알 수 있게 주사무소 등기소에 등기합니다.","이자·부양료·급료·사용료 그 밖에 1년 이내의 기간으로 정한 금전 또는 물건의 지급을 목적으로 한 채권":"이자나 급료처럼 한 해 이내 주기로 정기적으로 지급하는 채권은 단기소멸시효 대상입니다.","이중매매에 제2매수인이 적극 가담한 매매·증여":"매도인의 배임에 둘째 매수인이 적극적으로 끼어든 이중매매는 사회질서 위반으로 무효입니다.","이해관계인이나 검사의 청구가 있으면 법원은 부재자가 정한 재산관리인에게도 제1항·제2항의 처분을 명할 수 있다":"생사 불명이면 부재자가 정한 관리인에게도 법원이 앞의 처분 규정에 따라 명령을 내릴 수 있어요.","이행기부터 진행한다. 매매대금채권이 소유권이전등기청구권과 동시이행 관계에 있어도 지급기일 이후 시효가 진행한다":"동시이행의 항변권이 붙어 있어도 이행기가 지나면 시효가 진행하고 대금채권도 지급기일 이후 시효가 흐릅니다.","이행의 청구는 취소권자가 상대방에게 하는 청구이다":"법정추인이 되려면 취소권자가 상대에게 이행을 청구해야 하며 반대 방향의 청구는 해당하지 않습니다.","인지청구권에는 실효의 법리가 적용되지 않는다":"인지청구권은 오래 행사하지 않았더라도 실효의 법리로 막을 수 없는 권리입니다.","일부 추인이나 내용을 변경한 추인은 상대방의 동의를 얻어야 유효하다":"본인이 일부만 추인하거나 조건을 바꿔 추인하려면 상대방의 동의를 얻어야 효력이 있습니다.","일용품의 구입 등 일상생활에 필요하고 그 대가가 과도하지 아니한 법률행위는 성년후견인이 취소할 수 없다":"생필품 구입처럼 일상에 필요하고 값이 과하지 않은 행위는 성년후견인도 취소하지 못합니다.","임시이사와 특별대리인은 서로 다른 기관이다":"임시이사는 이사 공백을 메우는 기관이고 특별대리인은 이익 충돌 사항만 맡는 별개의 기관이에요.","임의규정(선량한 풍속 기타 사회질서에 관계없는 규정)과 다른 의사를 표시한 때에는 그 의사에 의한다":"사회질서와 무관한 임의규정은 당사자가 다르게 약속하면 그 약속이 우선합니다.","임의규정과 다른 의사표시가 있으면 그에 의한다. 임의규정과 다른 관습이 있는 경우 당사자의 의사가 명확하지 아니한 때에는 그 관습에 의한다":"의사표시가 임의규정보다 우선하고 의사가 불분명할 때만 임의규정과 다른 관습이 기준이 됩니다.","임의대리권의 범위는 원칙적으로 수권행위에 의하여 정해진다":"본인이 위임해서 생긴 대리권은 본인이 수권행위로 맡긴 범위만큼으로 정해집니다.","임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다":"임의대리인은 본인이 승낙하거나 부득이한 사정이 있을 때만 복대리인을 둘 수 있습니다.","입원환자의 휴대품 도난 방지 조치를 강구할 보호의무가 있다":"병원은 입원환자의 휴대품이 도난당하지 않도록 조치할 보호의무를 신의칙상 집니다.","자치법규로서 규범적 성질을 가진다(계약이 아니다)":"정관은 당사자 사이의 계약이 아니라 단체의 구성원 모두에게 적용되는 자치법규입니다.","재단법인의 기본재산을 새롭게 편입하는 행위나 처분하는 행위는 정관변경에 해당하여 주무관청의 허가가 필요하다":"기본재산을 늘리거나 처분하는 것은 정관을 바꾸는 일이라 주무관청의 허가를 받아야 합니다.","재단법인의 목적을 달성할 수 없는 때 설립자나 이사는 주무관청의 허가를 얻어 설립의 취지를 참작하여 그 목적 기타 정관의 규정을 변경할 수 있다":"목적을 이룰 수 없으면 주무관청 허가를 받아 설립 취지를 참작해 목적을 바꿀 수 있어요.","재단법인의 정관은 그 변경방법을 정관에 정한 때에 한하여 변경할 수 있다":"재단법인은 정관에 변경 방법을 정해 둔 경우에만 그 방법에 따라 정관을 바꿀 수 있습니다.","재산을 관리하는 아버지·어머니 또는 후견인에 대한 제한능력자의 권리는 능력자가 되거나 후임 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 아니한다":"재산을 관리하는 부모나 후견인에게 갖는 제한능력자의 권리는 능력자가 된 후 6개월간 시효가 완성되지 않습니다.","재판상의 청구(제170조), 파산절차참가(제171조), 지급명령(제172조), 화해를 위한 소환·임의출석(제173조), 최고(제174조)":"청구에 해당하는 구체적 방법으로 소송, 파산절차 참가, 지급명령, 화해를 위한 소환과 출석, 최고가 있습니다.","전지에 임한 자, 침몰한 선박 중에 있던 자, 추락한 항공기 중에 있던 자 그 밖의 위난을 당한 자의 생사가 전쟁종지·선박침몰·항공기 추락 그 밖의 위난 종료 후 1년간 분명하지 아니한 때":"전쟁이나 선박 침몰 같은 위난이 끝난 뒤 1년 동안 생사를 모르면 특별실종 요건이 채워집니다.","전통사찰 주지직 양도 약정을 알고도 묵인하고 한 주지 임명행위":"전통사찰의 주지직을 양도하기로 한 약정을 알면서 묵인한 채 임명한 행위는 반사회질서가 아닙니다.","점유권은 시효에 걸리지 아니한다":"점유권은 사실상 지배 상태 자체를 보호하는 권리로 오래 행사하지 않아도 시효로 소멸하지 않습니다.","정관 기재(제41조)와 등기(제60조) 모두 있어야 제3자에게 미친다":"대표권 제한이 제삼자에게까지 효력을 가지려면 정관 기재와 등기가 모두 갖춰져야 합니다.","정관으로 지정한 자 → 지정이 없거나 지정방법이 없으면 이사 또는 청산인이 주무관청의 허가를 얻어 법인의 목적과 유사한 목적을 위하여 처분(사단법인은 총회의 결의 필요) → 처분되지 않은 재산은 국고에 귀속":"남은 재산은 정관 지정자에게, 없으면 허가를 받아 비슷한 목적에 쓰고, 그래도 남으면 국고로 갑니다.","정관의 변경은 주무관청의 허가를 얻지 아니하면 효력이 없다. 법원의 허가가 아니다":"정관 변경은 법원이 아니라 주무관청의 허가를 받아야 효력이 생깁니다.","정년 60세는 만 60세에 도달하는 날을 말하는 것으로 본다(만 60세가 만료되는 날이 아니다)":"정년은 만 60세가 되는 날을 가리키며 만 60세를 꽉 채워 끝나는 날을 뜻하지 않습니다.","정당한 이유의 유무는 대리행위 당시를 기준으로 판단한다":"상대가 권한이 있다고 믿을 정당한 이유가 있었는지는 대리행위를 한 시점을 기준으로 봅니다.","정신적 제약으로 사무를 처리할 능력이 부족한 사람":"한정후견은 사무 처리 능력이 아예 없는 정도가 아니라 부족한 사람을 대상으로 합니다.","정신적 제약으로 일시적 후원 또는 특정한 사무에 관한 후원이 필요한 사람":"특정후견은 한시적이거나 특정 일에 대해서만 도움이 필요한 사람을 대상으로 합니다.","정지조건 있는 법률행위는 조건이 성취한 때로부터 효력이 생긴다":"정지조건은 조건이 이루어진 순간부터 법률행위가 비로소 효력을 갖게 하는 조건입니다.","정한 때에만 기재하는 사항이다(필요적 기재사항 중 정한 때에 한한다)":"존립시기와 해산사유는 실제로 정했을 때에만 정관에 쓰면 되므로 항상 적을 필요는 없어요.","제100조 제2항은 임의규정이다. 당사자는 주물을 처분할 때 특약으로 종물을 제외하거나 종물만을 별도로 처분할 수 있다":"종물 규정은 당사자가 다르게 정하면 물러나서 주물만 파는 특약이나 종물만 따로 파는 것이 가능합니다.","제100조 제2항의 처분에는 공법상 처분도 포함된다. 주물의 권리관계가 공법상 처분에 의하여 생긴 경우에도 적용된다":"종물이 주물을 따르는 규칙은 매매 같은 사법상 처분뿐 아니라 행정처분에도 적용됩니다.","제109조 제1항은 임의규정이다. 당사자의 합의로 그 적용을 배제할 수 있다":"착오 취소 규정은 임의규정이라 당사자가 합의하면 그 적용을 빼 버릴 수 있습니다.","제125조·제129조는 선의·무과실이, 제126조는 정당한 이유(상대방의 선의·무과실)가 필요하다":"표현대리가 성립하려면 상대방이 선의이고 무과실이어야 하며 권한 초과의 경우엔 이것을 정당한 이유라고 부릅니다.","제126조의 제3자는 표현대리행위의 직접 상대방만을 뜻한다. 전득자는 포함되지 않는다":"권한 초과 표현대리의 제삼자는 그 행위의 직접 상대방만을 가리키고 전득자는 해당하지 않습니다.","제17조 제2항이 적용되지 않는다. 동의가 있는 것처럼 속여도 피성년후견인은 취소할 수 있다":"동의를 받은 것처럼 속여도 피성년후견인은 이 제한에서 빠져 여전히 취소할 수 있습니다.","제26조 제1항·제2항은 생사가 분명하지 아니한 경우 부재자가 정한 재산관리인에게 준용한다":"관리인의 보존 처분과 담보 규정은 생사가 불분명할 때 부재자가 정한 관리인에게도 적용됩니다.","제3자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권의 범위 내에서 책임이 있다. 제3자가 대리권 없음을 알았거나 알 수 있었을 때에는 책임이 없다":"대리권을 줬다고 상대에게 알린 사람은 그 범위에서 책임지지만 상대가 대리권이 없음을 알았거나 알 수 있었다면 면합니다.","제3자의 사기로 계약을 체결한 표의자는 계약을 취소하지 않은 상태에서도 제3자에 대하여 불법행위로 인한 손해배상을 청구할 수 있다":"제삼자의 사기로 계약했다면 계약을 취소하지 않았어도 그 제삼자에게 불법행위 손해배상을 청구할 수 있습니다.","제3자의 선의는 추정되며 무과실은 요구되지 않는다. 과실이 있어도 보호된다":"제삼자는 선의로 추정되고 과실이 있어도 보호받으므로 무과실까지 입증할 필요가 없습니다.","제한능력자, 착오로 인하거나 사기·강박에 의하여 의사표시를 한 자, 그의 대리인 또는 승계인만이 취소할 수 있다. 제한능력자도 단독으로 취소권을 행사할 수 있다":"취소는 제한능력자, 착오나 사기와 강박을 당한 사람, 그 대리인과 승계인만 할 수 있고 제한능력자도 혼자 취소합니다.","제한능력자가 맺은 계약은 추인이 있을 때까지 상대방이 철회할 수 있다. 다만 상대방이 계약 당시에 제한능력자임을 알았던 경우에는 철회할 수 없다":"상대방은 추인 전까지 계약을 철회할 수 있지만 계약 때 제한능력자임을 알았다면 철회하지 못합니다.","제한능력자가 속임수로써 자기를 능력자로 믿게 한 경우 그 행위를 취소할 수 없다":"제한능력자가 속임수로 상대를 믿게 했다면 보호할 이유가 없어 자기 행위를 취소하지 못합니다.","제한능력자도 단독으로 취소권을 행사할 수 있다":"제한능력자는 법정대리인의 동의 없이도 자신의 행위를 혼자 취소할 수 있습니다.","제한능력자의 단독행위는 추인이 있을 때까지 상대방이 거절할 수 있다":"제한능력자가 혼자 한 단독행위는 추인 전까지 상대방이 받아들이지 않겠다고 거절할 수 있습니다.","조건의사와 그 표시가 필요하다. 조건의사가 있어도 외부에 표시되지 않으면 원칙적으로 법률행위의 동기에 불과하다":"조건이 되려면 마음속 의사와 이를 겉으로 드러낸 표시가 필요하고 표시되지 않으면 단지 동기일 뿐입니다.","조건의 성취가 미정한 권리의무는 일반규정에 의하여 처분, 상속, 보존 또는 담보로 할 수 있다":"조건부 권리와 의무도 아직 확정되지 않았을 뿐이어서 일반 규정에 따라 처분하고 상속하고 담보로 삼을 수 있습니다.","조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때 상대방은 그 조건이 성취한 것으로 주장할 수 있다":"손해를 입을 쪽이 일부러 조건 성취를 방해하면 상대는 조건이 이뤄진 것으로 주장할 수 있습니다.","조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취한 것으로 주장할 수 있다":"손해를 볼 쪽이 부당하게 조건 성취를 막았다면 상대는 조건이 이뤄진 것으로 주장할 수 있습니다.","조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때 상대방은 그 조건이 성취하지 아니한 것으로 주장할 수 있다":"이익을 볼 쪽이 부당하게 조건을 이뤄 냈다면 상대는 조건이 성취되지 않은 것으로 주장할 수 있습니다.","조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때에는 상대방은 그 조건이 성취되지 아니한 것으로 주장할 수 있다":"이익을 볼 쪽이 부당하게 조건을 이뤄 냈다면 상대는 조건이 이뤄지지 않은 것으로 다룰 수 있습니다.","조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위 전부를 무효로 한다(조건만이 무효가 아니다)":"불법한 조건이 붙으면 조건만 떼어 내지 않고 그 조건이 붙은 법률행위 전체가 무효가 됩니다.","조건이 성취된 때부터 시효가 진행된다":"정지조건부 권리는 조건이 이뤄져 권리를 행사할 수 있게 된 때부터 시효가 진행합니다.","조건 있는 법률행위의 당사자는 조건의 성부가 미정한 동안에 조건의 성취로 인하여 생길 상대방의 이익을 해하지 못한다":"조건이 이뤄질지 정해지지 않은 동안에도 당사자는 조건이 성취되면 상대가 얻을 이익을 해칠 수 없습니다.","존립기간의 만료, 법인의 목적의 달성 또는 달성의 불능, 그 밖에 정관에 정한 해산사유의 발생, 파산, 설립허가의 취소":"법인은 존립기간 만료, 목적 달성이나 불능, 정관 사유 발생, 파산, 허가 취소로 해산합니다.","존립시기·해산사유(제40조 제7호)는 필요적 기재사항이 아니다":"재단법인 정관에는 존립시기와 해산사유를 필수로 적지 않아도 됩니다.","종래의 주소나 거소를 떠난 자가 재산관리인을 정하지 아니한 때에는 법원은 이해관계인이나 검사의 청구에 의하여 재산관리에 관하여 필요한 처분을 명하여야 한다":"떠난 사람이 관리인을 안 정했다면 이해관계인이나 검사의 청구로 법원이 필요한 처분을 명합니다.","종래의 주소를 중심으로 하는 사법상 법률관계에 한한다. 생존한 실종자가 다른 곳에서 한 법률행위는 유효하다":"사망 간주는 떠난 주소 중심의 사법관계에만 미쳐서 다른 곳에서 한 실종자의 행위는 유효합니다.","종물은 주물의 처분 당시 존재하여야 하며, 저당권의 효력은 설정행위에 다른 약정이 없으면 종물에 미친다":"주물 처분 때 있던 종물에만 효력이 미치고 저당권도 특약이 없으면 종물에까지 미칩니다.","종물은 주물의 처분에 따른다":"주물을 팔거나 저당 잡힐 때 종물도 따로 약속하지 않아도 함께 처분됩니다.","주된 권리의 소멸시효가 완성한 때에는 종속된 권리에 그 효력이 미친다":"원금 채권의 시효가 끝나면 거기에 딸린 이자 같은 종속된 권리도 함께 소멸합니다.","주로 자기의 채무 이행만을 회피할 목적으로 동시이행항변권을 행사하는 것은 권리남용이 될 수 있다":"자기 채무를 피하려는 목적으로만 동시이행항변권을 내세우면 권리남용이 될 수 있습니다.","주무관청은 법인의 사무를 검사·감독한다":"주무관청은 법인이 제대로 운영되는지 사무를 조사하고 지도할 권한이 있습니다.","주물과 종물은 각각 독립한 물건이다. 법률상 하나의 물건으로 취급되지 않는다":"종물은 주물과 법적으로 별개의 물건이지만 처분에서만 운명을 같이한다는 의미입니다.","주물과 종물의 법리는 주된 권리와 종된 권리 상호간에도 유추적용된다":"물건 사이의 주종 관계 원리가 권리 사이의 주된 권리와 종된 권리에도 비슷하게 적용됩니다.","주물 소유자의 상용에 공여되고 있더라도 주물 자체의 효용과 관계가 없는 물건은 종물이 아니다":"주인이 쓰고 있어도 주물 자체의 효용과 무관한 물건이라면 종물로 인정되지 않습니다.","주물을 점유에 의하여 시효취득하여도 종물을 점유하지 않았다면 그 효력은 종물에 미치지 않는다":"주물을 시효로 취득해도 종물을 실제로 점유하지 않았다면 종물까지 취득하는 것은 아닙니다.","주물의 구성부분은 종물이 될 수 없다":"주물 자체를 이루는 부분은 독립한 물건이 아니므로 따로 종물로 볼 수 없습니다.","주소를 알 수 없으면 거소를 주소로 본다. 국내에 주소 없는 자의 거소도 주소로 본다":"주소를 모르거나 국내에 주소가 없으면 실제로 머무는 거소를 주소처럼 다룹니다.","주유소의 주유기는 특별한 사정이 없는 한 주유소 건물의 종물이다":"주유소 영업에 필요한 주유기는 건물을 계속 쓰는 데 도움이 되므로 건물의 종물로 봅니다.","중단까지 경과한 시효기간은 산입하지 아니하고 중단사유가 종료한 때부터 새로이 진행한다. 재판상의 청구로 중단한 시효는 재판이 확정된 때부터 새로이 진행한다":"중단되면 그전에 지난 기간은 버려지고 사유가 끝난 때부터 새로 세며 소송으로 중단했다면 판결이 확정된 때부터입니다.","중요한 사유가 있는 때 법원이 직권 또는 이해관계인·검사의 청구로 해임할 수 있다":"청산인에게 중대한 문제가 있으면 법원이 직권이나 청구에 따라 청산인을 해임할 수 있습니다.","진의 아님을 알았거나 알 수 있었다는 사실(상대방의 악의·과실)은 무효를 주장하는 사람이 증명하여야 한다":"상대가 진의 아님을 알았거나 알 수 있었다는 점은 무효를 주장하는 쪽이 증명해야 합니다.","진정서를 낸 뒤 취하를 조건으로 거액의 급부를 받기로 한 약정":"진정서를 내고 취하하는 대가로 거액을 받기로 한 약정은 정당한 범위를 넘어 사회질서에 반합니다.","질병·장애·노령 그 밖의 사유로 인한 정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람. 일시적 부족자에게는 허용되지 않는다":"사무 처리 능력이 지속적으로 없는 사람이 대상이며 일시적으로 부족한 사람은 해당하지 않아요.","착오로 인하여 표의자가 경제적 불이익을 입은 것이 아니라면 법률행위 내용의 중요부분의 착오라고 할 수 없다":"착오 때문에 경제적 손해를 본 것이 아니라면 법률행위 내용의 중요부분 착오로 인정되지 않습니다.","착오로 인한 취소로 상대방이 손해를 입더라도 착오자는 불법행위로 인한 손해배상책임을 부담하지 않는다(경과실의 경우도 취소로 인한 손해배상책임 없음)":"착오로 취소해서 상대가 손해를 봐도 착오자는 불법행위 책임을 지지 않아 경과실이면 배상도 없습니다.","채권·물권적 청구권. 물권적 청구권은 형성권이 아니라 청구권이다":"청구권은 상대에게 일정한 행위를 요구하는 권리이고, 물권적 청구권도 여기에 속합니다.","채권 및 소유권 이외의 재산권은 20년간 행사하지 아니하면 소멸시효가 완성한다":"지상권 같은 채권과 소유권 외의 재산권은 20년 동안 쓰지 않으면 소멸시효가 완성됩니다.","채권은 10년간 행사하지 아니하면 소멸시효가 완성한다":"일반 채권은 10년 동안 권리를 쓰지 않으면 시효가 끝나 청구할 수 없게 됩니다.","채권이 성립한 때부터 진행한다":"기한이 없는 채권은 언제든 청구할 수 있어서 채권이 성립한 때부터 바로 시효가 진행합니다.","채권자가 기한이익 상실의 의사표시(청구)를 한 때부터 전액에 대해 진행한다":"채권자가 남은 전액을 청구해 기한이익을 잃게 한 때부터 전액에 대한 시효가 진행합니다.","채권자가 법정기간 내에 가집행신청을 하지 아니함으로 인하여 그 효력을 잃은 때에는 시효중단의 효력이 없다. 지급명령에 의한 시효중단의 효과는 지급명령을 신청한 때에 발생한다":"지급명령이 효력을 잃으면 중단 효력도 없고 중단의 효과는 지급명령을 신청한 시점에 소급하여 발생합니다.","채권자가 이를 취소하거나 그 청구가 각하된 때에는 시효중단의 효력이 없다":"파산절차 참가를 채권자가 취소하거나 참가 청구가 각하되면 시효중단 효력이 생기지 않습니다.","채권행위/물권행위, 처분행위/의무부담행위, 요식행위/불요식행위, 유인행위/무인행위, 유상행위/무상행위, 생전행위/사후행위":"법률행위는 효과, 방식, 원인 유무, 대가 유무, 시기 등의 기준에 따라 여러 쌍으로 나눕니다.","채무의 승인, 채권양도의 통지, 사원총회소집 통지 등":"채무 승인이나 양도 통지는 어떤 사실을 알리는 행위로 관념의 통지에 해당하는 준법률행위입니다.","채무자가 담보를 손상·감소 또는 멸실하게 한 때, 채무자가 담보제공의무를 이행하지 아니한 때 기한의 이익을 주장하지 못한다":"채무자가 담보를 해치거나 담보 제공 의무를 어기면 갚는 시기를 미룰 수 있는 이익을 잃습니다.","채무자가 제기한 소에 대하여 채권자가 응소하여 그 소송에서 적극적으로 권리를 주장하고 그것이 받아들여진 경우 재판상의 청구가 될 수 있다":"채무자가 건 소송에서 채권자가 방어에 그치지 않고 적극적으로 권리를 주장해 인정받으면 재판상 청구로 봅니다.","채무자의 법률행위가 통정허위표시인 경우에도 채권자취소권의 대상이 될 수 있다":"채무자가 짜고 한 허위 행위라도 채권자는 채권자취소권으로 그 행위를 다툴 수 있습니다.","처분을 허락한 재산에 관하여도 법정대리인의 대리권은 소멸하지 않는다. 법정대리인은 그 재산에 관하여 유효한 대리행위를 할 수 있다":"처분을 허락했어도 법정대리인의 대리권은 남아 있어서 그 재산을 대신 처분할 수 있습니다.","처음부터 아무 대리권도 없었던 사람의 대리행위에는 대리권 소멸 후의 표현대리를 유추적용할 수 없다":"처음부터 대리권이 한 번도 없던 사람의 행위에는 소멸 후의 표현대리 규정을 끌어다 쓸 수 없습니다.","천재 기타 사변으로 소멸시효를 중단할 수 없을 때에는 그 사유가 종료한 때부터 1개월 내에는 시효가 완성되지 아니한다":"천재지변으로 시효를 중단할 수 없었다면 그 사유가 끝난 때부터 1개월은 시효가 완성되지 않습니다.","철회·거절의 의사표시는 제한능력자에게도 할 수 있다":"상대방이 철회나 거절을 통지할 때 법정대리인이 아니라 제한능력자 본인에게 해도 효력이 있어요.","청구권에 관하여 제척기간을 정하고 있더라도(예: 매도인의 하자담보책임에 기한 손해배상청구권) 그 청구권에 소멸시효 규정이 적용될 수 있다":"하자담보로 인한 배상청구권처럼 제척기간이 있어도 그 청구권에는 소멸시효 규정도 함께 적용될 수 있습니다.","청구권자: 본인, 배우자, 4촌 이내의 친족, 성년후견인, 성년후견감독인, 검사, 지방자치단체의 장":"취소 범위를 바꿔 달라고 청구할 수 있는 사람은 본인, 가까운 친족, 후견 관련자, 검사, 지자체장이에요.","청구권자가 이해관계인 또는 검사이며, 요건이 충족되면 법원은 실종선고를 하여야 한다(필요적)":"요건을 갖춘 청구가 있으면 법원에게 재량이 없고 실종선고를 반드시 해야 한다는 뜻이에요.","청구 후 2주간 내에 이사가 소집절차를 밟지 아니하면 청구한 사원이 법원의 허가를 얻어 소집할 수 있다":"청구하고 2주간 이사가 움직이지 않으면 청구한 사원이 법원 허가를 받아 직접 소집합니다.","청산에서 제외된 채권자는 법인의 채무를 완제한 후 귀속권리자에게 인도하지 아니한 재산에 대하여서만 변제를 청구할 수 있다":"청산에서 빠진 채권자는 빚을 다 갚고 귀속권리자에게 넘기지 않은 재산에서만 변제를 청구할 수 있습니다.","청산이 종결한 때 청산인은 3주간 내에 등기하고 주무관청에 신고하여야 한다":"청산이 끝나면 청산인은 3주간 안에 종결 등기를 하고 주무관청에도 신고해야 합니다.","청산인에게 준용되는 규정: 제58조 제2항(과반수 결정), 제59조~제62조(대표권, 제한 등기, 직무대행자, 주의의무, 대리인 선임), 제64조(특별대리인), 제65조(임무해태), 제70조(임시총회)":"청산인에게는 이사에 관한 과반수 결정, 대표권, 주의의무, 특별대리인, 임시총회 규정이 준용됩니다.","청산인은 알고 있는 채권자에게 각각 채권신고를 최고하여야 한다. 알고 있는 채권자는 청산에서 제외하지 못한다":"청산인이 아는 채권자에게는 일일이 신고를 알려야 하고, 알고 있는 채권자는 청산에서 빼지 못합니다.","청산인은 채권신고기간 내에는 채권자에게 변제하지 못한다. 그러나 법인은 채권자에 대한 지연손해배상의무를 면하지 못한다":"신고 기간 중에는 갚을 수 없지만 그동안의 지연 손해배상 의무는 법인이 그대로 집니다.","청산인은 취임한 날부터 2월 내에 3회 이상의 공고로 채권자에게 일정한 기간 내에 채권을 신고할 것을 최고하여야 한다. 신고기간은 2월 이상이어야 한다":"청산인은 취임 후 2월 안에 3회 이상 공고해 채권자에게 신고를 재촉하며 신고 기간은 2월 이상이어야 합니다.","청산인은 파산으로 해산한 경우가 아니면 취임 후 3주일 내에 해산 사유와 해산 연월일, 청산인의 성명·주소, 청산인의 대표권을 제한한 경우 그 제한을 주사무소 소재지에서 등기한다":"파산이 아닌 해산이면 청산인은 취임 후 3주일 안에 해산 사유와 청산인 정보를 주사무소에서 등기합니다.","청산인은 파산의 경우를 제외하고 취임 후 3주간 내에 제85조 제1항의 사항을 주무관청에 신고한다. 청산 중 취임한 청산인은 성명·주소만 신고한다":"청산인은 3주간 안에 등기한 사항을 주무관청에 신고하고, 청산 중에 취임한 청산인은 성명과 주소만 신고합니다.","청산인이 될 자가 없거나 결원으로 손해가 생길 염려가 있는 때 법원이 직권 또는 이해관계인·검사의 청구로 선임할 수 있다":"청산인이 없어 손해 우려가 있으면 법원이 직권이나 청구에 따라 청산인을 정할 수 있습니다.","청산종결등기가 마쳐진 경우에도 청산사무가 종료되지 않았다면 그 범위에서 청산법인으로 존속한다":"종결등기를 했어도 정리할 일이 남아 있으면 그 범위에서는 청산법인으로 여전히 존재합니다.","청산 중 법인의 재산이 채무를 완제하기에 부족함이 분명하게 된 때 청산인은 지체 없이 파산선고를 신청하고 공고하여야 한다. 청산인은 파산관재인에게 사무를 인계함으로써 임무가 종료된다":"재산이 빚에 못 미치는 것이 분명해지면 청산인은 파산을 신청하고 사무를 파산관재인에게 넘겨 임무를 마칩니다.","청산 중의 법인은 변제기에 이르지 아니한 채권에 대하여도 변제할 수 있다. 조건 있는 채권, 존속기간이 불확정한 채권, 가액이 불확정한 채권은 법원이 선임한 감정인의 평가에 의하여 변제한다":"청산 중에는 아직 기한이 안 된 채권도 갚을 수 있고 조건부나 가액 불확정 채권은 감정인 평가액으로 갚습니다.","청약과 승낙의 의사표시가 합치하여 성립하는 법률행위이다":"계약은 한쪽의 청약과 다른 쪽의 승낙이 서로 맞아떨어질 때 만들어지는 법률행위입니다.","청약의 의사표시는 그 표시가 상대방에게 도달한 때에 효력이 생긴다":"청약도 도달주의를 따라서 상대방에게 닿은 순간부터 효력이 발생합니다.","초일불산입 원칙은 임의규정이다. 당사자의 합의로 달리 정할 수 있다":"첫날을 빼고 세는 원칙은 임의규정이라 당사자가 합의로 첫날을 넣도록 바꿀 수 있습니다.","초일불산입으로 6월 2일 0시부터 시작하여 6월 3일 24시에 만료한다":"첫날을 빼고 다음 날 영시부터 세므로 이틀짜리 기간은 그 다음 날의 끝에 만료합니다.","총사원 3분의 2 이상의 동의가 있어야 한다. 정수에 관하여 정관에 다른 규정이 있으면 그에 의한다":"정관을 바꾸려면 총사원 3분의 2 이상이 동의해야 하며 정관에 다른 수를 정했으면 그에 따릅니다.","총유물에 관한 사원의 권리의무는 사원의 지위의 취득·상실로 취득·상실된다":"총유물에 대한 사원의 권리와 의무는 사원 자격을 얻으면 생기고 자격을 잃으면 함께 없어집니다.","총유물의 매매계약 체결은 총유물의 처분행위에 해당하여 사원총회의 결의가 필요하다":"총유물을 파는 계약은 처분행위이므로 사원총회의 결의를 거쳐야 합니다.","총회는 통지한 사항에 관하여서만 결의할 수 있다. 정관에 다른 규정이 있으면 그에 의한다":"총회는 미리 통지한 안건만 의결할 수 있어 통지에 없던 사항은 의결하지 못합니다.","총회의 결의는 본법 또는 정관에 다른 규정이 없으면 사원 과반수의 출석과 출석사원의 결의권의 과반수로 한다. 서면·대리인으로 결의권을 행사하는 사원은 출석한 것으로 본다":"사원 과반수가 출석해 출석 사원 의결권의 과반수로 정하며 서면이나 대리 의결도 출석으로 칩니다.","총회의 의사에 관하여는 의사록을 작성하고 의사의 경과·요령·결과를 기재하여 의장 및 출석한 이사가 기명날인한다. 이사는 의사록을 주된 사무소에 비치한다":"총회 진행 과정과 결과를 의사록에 적고 의장과 출석 이사가 서명해 주된 사무소에 둡니다.","최고·거절 등. 무권대리인의 상대방이 본인에게 하는 추인 여부의 확답 최고는 의사의 통지로서 준법률행위이다":"최고나 거절은 의사를 알리는 행위이고 효과는 법이 정하므로 준법률행위로 분류됩니다.","추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 그 상대방에게 대항하지 못한다. 상대방이 그 사실을 안 때에는 그러하지 아니하다. 무권대리인에게 한 추인도 상대방이 알면 효력이 있다":"추인이나 거절은 상대방에게 해야 맞설 수 있지만 상대가 그 사실을 알면 무권대리인에게 한 추인도 유효합니다.","추인은 무권대리행위가 있음을 알고 하여야 한다. 무권대리인의 동의는 필요 없다":"본인은 무권대리가 있었다는 점을 알고 추인해야 하며 무권대리인의 동의는 필요하지 않습니다.","추인은 묵시적으로 할 수 있다. 다만 무권대리행위가 범죄가 되는 경우 장기간 형사고소를 하지 않았다는 사실만으로 묵시적 추인이 인정되지 않는다":"추인은 행동으로도 할 수 있지만 범죄 사안에서 오래 고소하지 않았다는 이유만으로는 인정하지 않습니다.","추인은 취소의 원인이 소멸된 후에 하여야만 효력이 있다. 법정대리인 또는 후견인이 추인하는 경우에는 이 제한이 없다":"본인이 추인하려면 사기나 제한능력 같은 원인이 끝난 뒤여야 하지만 법정대리인이나 후견인의 추인은 제한이 없습니다.","추인할 수 있는 후에 → 아래 사유가 있고 → 이의를 보류하지 아니하였을 것 → 사유 6가지: ① 전부나 일부의 이행 ② 이행의 청구 ③ 경개 ④ 담보의 제공 ⑤ 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 ⑥ 강제집행":"추인할 수 있는 때 이후에 이행이나 청구 같은 여섯 가지 행위를 이의 없이 하면 추인한 것으로 보는 법정추인입니다.","취소권은 재판상이든 재판 외이든 제146조의 기간 내에 행사하면 된다":"취소권은 소송으로 하든 소송 밖에서 통지로 하든 기간 안에 행사하기만 하면 됩니다.","취소권은 추인할 수 있는 날부터 3년 내, 법률행위를 한 날부터 10년 내에 행사한다":"착오 취소권도 추인할 수 있는 날과 행위한 날을 각각 기준으로 한 두 기간 안에 써야 합니다.","취소권은 추인할 수 있는 날부터 3년 내에, 법률행위를 한 날부터 10년 내에 행사하여야 한다":"취소권은 이 두 기간 안에 행사해야 하며 기준일이 추인 가능일과 행위일로 서로 다릅니다.","취소권의 3년·10년 제한(제146조)은 무효행위의 추인에 적용되지 않는다":"취소권에 있는 3년과 10년의 기간 제한은 무효행위를 추인하는 경우에는 적용되지 않습니다.","취소권자가 추인할 수 있은 후에 이의를 보류한 상태에서 취소할 수 있는 계약을 이행한 때":"이의를 보류하고 이행했다면 계약을 인정한 것이 아니라서 법정추인이 되지 않습니다.","취소권자가 취득한 권리의 양도":"취소권자가 계약으로 얻은 권리를 남에게 넘기는 것은 계약을 인정하는 행동이라 법정추인이 됩니다.","취소권자의 상대방이 취소권자에게 이행을 청구하는 것":"상대방이 취소권자에게 이행을 요구하는 것은 취소권자의 행위가 아니라서 법정추인이 되지 않습니다.","취소권자의 상대방이 취소할 수 있는 행위로 취득한 권리를 제3자에게 양도하는 것":"상대방이 얻은 권리를 제삼자에게 넘기는 것은 취소권자가 한 일이 아니므로 법정추인 사유가 아닙니다.","취소는 선의의 제3자에게 대항하지 못한다":"착오를 이유로 취소해도 그 사실을 모르고 거래한 제삼자에게는 효력을 주장하지 못합니다.","취소된 법률행위는 처음부터 무효로 본다. 제한능력자는 현존이익의 한도에서 상환할 책임이 있다(선의·악의 불문)":"취소되면 서로 돌려줘야 하지만 제한능력자는 남아 있는 이익만큼만 갚으면 됩니다.","취소된 법률행위는 처음부터 무효인 것으로 본다. 다만 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환할 책임이 있다(선의·악의 불문)":"취소되면 처음부터 무효로 취급되며 제한능력자는 받은 이익이 남은 만큼만 선악과 무관하게 갚습니다.","취소된 법률행위도 무효행위의 추인 요건(제139조)으로 추인할 수 있다":"이미 취소되어 무효가 된 행위도 무효행위의 추인 요건을 갖추면 새 행위로 추인될 수 있습니다.","취소 원인이 종료되어 취소권행사에 관한 장애가 없어지고 취소권자가 추인할 수도 취소할 수도 있는 상태가 된 때":"추인할 수 있는 날은 사기나 제한능력 같은 원인이 끝나 취소와 추인 모두 자유로운 상태가 된 때입니다.","취소할 수 있는 법률행위는 제140조의 취소권자가 추인할 수 있고, 추인 후에는 취소하지 못한다":"취소권자가 추인하면 취소권을 포기한 것이어서 이후에는 같은 행위를 취소하지 못합니다.","취소할 수 있는 법률행위의 상대방이 확정한 경우 취소는 그 상대방에 대한 의사표시로 하여야 한다. 상대방이 취소할 수 있는 행위로 취득한 권리를 제3자에게 양도한 경우에도 취소의 의사표시는 원래의 상대방에게 한다. 양수인이 상대방이 되는 것이 아니다":"취소는 계약 상대방에게 의사표시로 하며 상대가 권리를 제삼자에게 넘겼어도 취소의 상대는 원래 상대방입니다.","타인 소유 부동산에 저당권을 취득하는 것, 보존등기를 마친 자로부터 전세권을 취득하는 것은 설정적 승계취득이다":"소유자의 권리에서 저당권이나 전세권을 새로 만들어 얻는 것은 설정적 승계취득에 해당합니다.","타인의 권리를 목적으로 하는 매매계약은 유효하다. 매도인은 권리를 취득하여 이전할 의무가 있다(제569조)":"남의 물건을 파는 계약도 유효하고 매도인은 그 권리를 취득해 넘겨줄 의무를 집니다.","타인의 권리에 기초하지 않고 새로 취득. 취득시효, 선의취득, 무주물 선점, 유실물 습득 소유권 취득, 매장물 발견, 부합·혼화·가공, 건물 신축 등":"원시취득은 남의 권리를 물려받지 않고 새로 권리를 얻는 방식으로 취득시효와 선의취득이 있습니다.","타인의 권리에 기초한 취득. 이전적 승계(매매·상속 등)와 설정적 승계(지상권·전세권·저당권 설정)가 있다":"승계취득은 앞사람의 권리를 바탕으로 얻는 방식이며 권리를 넘기는 이전과 새로 설정하는 설정이 있어요.","타인의 토지에 권원 없이 식재한 수목의 소유권은 토지에 부합되어 토지 소유자에게 속한다":"남의 땅에 권리 없이 심은 나무는 땅에 합쳐져 땅 주인의 소유가 됩니다.","토지 및 그 정착물은 부동산이다. 부동산 이외의 물건은 동산이다. 관리할 수 있는 자연력과 금전은 동산이다":"땅과 그 위에 붙은 것은 부동산이고, 나머지는 전기와 금전까지 모두 동산으로 분류됩니다.","토지소유자의 건물 철거 청구가 권리남용이 되어도 토지소유자는 건물 소유자에게 토지 사용대가를 부당이득으로 반환청구할 수 있다":"철거 청구가 막혀도 땅 주인은 건물 소유자에게 토지 사용 대가를 부당이득으로 돌려받을 수 있습니다.","특별한 절차가 필요한 행위(후견감독인 동의 등)는 기간 내에 그 절차를 밟은 확답을 발송하지 않으면 취소한 것으로 본다":"후견감독인 동의 같은 절차가 필요한 행위는 기간 안에 절차를 밟은 답이 없으면 취소로 간주합니다.","특정한 내용의 의사표시를 하고자 하는 표의자의 생각이다. 표의자가 진정으로 마음속에서 바라는 사항이 아니다":"진의는 어떤 표시를 하려는 생각 자체이며 마음속으로 진짜 원하는 결과와는 다릅니다.","특정한 법률행위를 위임한 경우 대리인이 본인의 지시에 좇아 행위한 때 본인은 자기가 안 사정 또는 과실로 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다":"본인이 지시해서 대리인이 한 행위라면 본인이 알았던 사정에 대해 대리인이 몰랐다고 주장하지 못합니다.","특정후견은 본인의 의사에 반하여 할 수 없다":"특정후견은 본인이 원하지 않으면 시작할 수 없어서 본인 의사가 절대 조건입니다.","특정후견은 심판에서 정한 기간이 지나면 종료 심판 없이 종료한다":"특정후견은 정해 둔 기간이 끝나면 따로 종료 심판을 받지 않아도 저절로 끝납니다.","특정후견은 피특정후견인의 행위능력을 제한하지 않는다":"특정후견은 도움을 줄 뿐이어서 피특정후견인은 여전히 모든 법률행위를 혼자 할 수 있습니다.","특정후견의 심판을 하는 경우에는 특정후견의 기간 또는 사무의 범위를 정하여야 한다":"특정후견을 정할 때는 도움을 줄 기간이나 맡길 사무의 범위를 반드시 함께 정해야 합니다.","파산채권자 전체의 이익을 대표하는 제3자이다. 파산관재인이 악의라도 파산채권자 중 선의자가 있으면 선의의 제3자로 인정되어 허위표시의 무효로 대항할 수 없다":"파산관재인이 악의여도 파산채권자 중에 선의자가 있으면 선의의 제삼자로 보아 무효를 주장하지 못합니다.","판결에 의하여 확정된 채권은 단기의 소멸시효에 해당한 것이라도 그 소멸시효는 10년으로 한다. 파산절차에 의하여 확정된 채권 및 재판상의 화해·조정 그 밖에 판결과 동일한 효력이 있는 것에 의하여 확정된 채권도 같다":"판결로 확정된 채권은 원래 단기시효였어도 10년으로 늘어나며 화해나 조정, 파산절차로 확정된 채권도 같습니다.","판결확정 당시에 변제기가 도래하지 아니한 채권에는 10년 연장 규정이 적용되지 않는다":"판결이 확정될 때 아직 갚을 때가 오지 않은 채권에는 시효를 10년으로 늘리는 규정이 적용되지 않습니다.","표시와 진의의 불일치가 상대방과 합의된 것이면 통정허위표시이다":"표시와 속마음이 다른 것을 상대방과 미리 짜고 했다면 비진의표시가 아니라 통정허위표시입니다.","표의자가 과실 없이 상대방을 알지 못하거나 상대방의 소재를 알지 못하는 경우 민사소송법 공시송달 규정에 의하여 송달할 수 있다":"상대를 모르거나 소재를 알 수 없으면 과실이 없는 경우 법원을 통한 공시송달로 의사표시를 전달할 수 있어요.","표의자가 그 점에 착오가 없었더라면 의사표시를 하지 않았을 것이라고 생각되고, 보통 일반인도 표의자의 처지에 섰더라면 그 의사표시를 하지 않았을 것이라고 생각될 정도로 중요한 부분":"본인과 보통 사람 모두 착오가 없었다면 그 의사표시를 하지 않았을 만큼 중요한 부분이 중요부분입니다.","표의자가 장래에 있을 어떤 사항의 발생이 미필적임을 알아 그 발생을 예기한 데 지나지 않는 경우, 그 기대가 이루어지지 않은 것을 착오로 볼 수 없다":"앞으로 일어날지 불확실하다는 것을 알고 기대만 했다면 이루어지지 않아도 착오라고 할 수 없습니다.","표의자를 기망하여 착오에 빠뜨리고 그 착오로 의사표시를 하게 하려는 고의(이중의 고의). 재산상 손실을 주려는 고의는 필요하지 않다":"속여 착각하게 하고 그 착각으로 의사표시를 하게 하려는 두 겹의 고의가 필요하고 재산상 손실을 줄 의도는 필요 없습니다.","표의자의 내심의 진의를 탐구한다. 당사자 쌍방이 모두 같은 의사로 어느 목적물을 정했으나 표시를 착오한 경우 그 일치한 의사대로 계약이 성립한다(오표시무해의 원칙)":"양쪽이 같은 대상을 뜻했으면 표시가 틀려도 그 일치한 의사대로 계약이 성립하는 오표시무해의 원칙입니다.","표의자의 중대한 과실 유무의 증명책임은 의사표시를 취소하지 못하게 하려는 상대방에게 있다":"취소를 막으려는 상대방이 표의자에게 중대한 과실이 있었음을 증명해야 합니다.","표현대리가 성립하면 상대방에게 과실이 있어도 과실상계의 법리를 유추적용하여 본인의 책임을 경감할 수 없다":"표현대리가 성립하면 상대에게 어느 정도 과실이 있어도 과실상계로 본인의 책임을 줄여 주지 못합니다.","피성년후견인도 의사능력이 있으면 유효하게 임의대리행위를 할 수 있다. 대리인은 행위능력자임을 요하지 않는다":"피성년후견인도 판단 능력이 있으면 대리인이 될 수 있어 본인이 행위능력자일 필요가 없습니다.","피성년후견인의 법률행위는 취소할 수 있다. 가정법원은 취소할 수 없는 피성년후견인의 법률행위의 범위를 정할 수 있다":"원칙은 취소할 수 있지만 법원이 취소할 수 없는 행위의 범위를 따로 정해 줄 수 있습니다.","피해자가 직무행위에 해당하지 아니함을 알았거나 중대한 과실로 알지 못한 때에는 법인에 책임을 물을 수 없다. 경과실로 알지 못한 경우에는 법인에게 책임을 물을 수 있다":"피해자가 직무가 아님을 알았거나 중대한 과실로 몰랐다면 법인에 책임을 묻지 못하고 경과실이면 물을 수 있어요.","하나의 물건에 대해 본인과 대리인이 각각 계약을 체결한 경우, 대리인이 체결한 계약도 유효하다":"본인과 대리인이 같은 물건에 각각 계약했더라도 대리인이 맺은 계약이 그 때문에 무효가 되지는 않습니다.","학생 및 수업자의 교육·의식 및 유숙에 관한 교주·숙주·교사의 채권":"학교나 기숙 시설 운영자가 학생에게 가지는 교육과 숙식 관련 채권은 가장 짧은 단기시효를 받습니다.","학술·종교·자선·기예·사교 그 밖의 영리 아닌 사업을 목적으로 하는 사단 또는 재단은 주무관청의 허가를 얻어 법인으로 할 수 있다":"돈 버는 것이 목적이 아닌 단체는 주무관청의 허가를 받아야 법인이 될 수 있습니다.","한정후견개시 시에도 본인의 의사를 고려하여야 한다(제9조 제2항 준용)":"한정후견을 시작할 때도 성년후견처럼 본인의 의사를 참작해야 한다는 규정을 가져옵니다.","한정후견인이 피한정후견인의 이익이 침해될 염려가 있음에도 동의하지 않으면 가정법원은 피한정후견인의 청구에 의하여 동의를 갈음하는 허가를 할 수 있다":"후견인이 이익이 침해될 우려에도 동의하지 않으면 법원이 동의를 대신하는 허가를 줄 수 있어요.","한정후견·특정후견 중 성년후견개시 심판을 하면 종전 한정후견·특정후견의 종료 심판을 한다":"한정이나 특정후견 중에 성년후견을 시작하면 앞선 후견은 종료 심판으로 정리됩니다.","할부채무는 1회 불이행만으로 전액에 대해 시효가 진행하지 않는다":"할부금을 한 번 안 냈다고 해서 남은 전액의 시효까지 한꺼번에 시작되는 것은 아닙니다.","해산한 법인은 청산의 목적 범위 내에서만 권리가 있고 의무를 부담한다":"해산한 법인은 정리 작업에 필요한 범위에서만 권리와 의무를 가지는 청산법인으로 남습니다.","해악을 고지하여 공포심을 일으키게 하고 그 공포심으로 의사표시를 하게 하는 것. 위법한 강박이어야 한다":"강박은 해를 입히겠다고 알려 두려움을 일으켜 그 두려움으로 의사표시를 하게 하는 것이며 위법해야 합니다.","해외 파견 교육연수를 받은 근로자가 일정 기간 근무하기로 한 약정":"해외 연수 후 일정 기간 근무하기로 한 약정은 정당한 범위라면 반사회질서에 해당하지 않습니다.","해제조건 있는 법률행위는 조건이 성취한 때로부터 효력을 잃는다":"해제조건은 이미 생긴 효력이 조건이 이루어지는 순간부터 없어지게 하는 조건입니다.","행위능력을 갖춘 미성년자에게는 특별한 사정이 없는 한 의사표시의 수령능력이 인정된다":"혼자 법률행위를 할 수 있는 미성년자는 의사표시를 받는 능력도 인정됩니다.","행위 당시 상대방이 대리인이라 칭하는 자의 대리권 없는 행위에 동의하거나 그 대리권을 다투지 아니한 때에 한하여 제130조~제135조를 준용한다. 대리권 없는 자에 대하여 그 동의를 얻어 단독행위를 한 때에도 같다":"단독행위의 무권대리는 상대가 행위 당시 대리인을 자처하는 자의 권한을 다투지 않았을 때에만 계약의 규정을 준용합니다.","행위의 외형상 객관적으로 직무행위로 보이는지로 판단한다. 대표자 개인의 이익을 위한 행위이거나 법령 규정에 위배된 행위라도 외형상 직무행위이면 직무에 관한 행위이다":"겉모습이 직무행위로 보이면 개인 이익이나 위법한 동기가 있어도 직무에 관한 행위로 취급합니다.","허위의 선급금 반환채무 부담행위에 기하여 그 채무를 보증하고 이행하여 구상권을 취득한 자":"거짓 채무를 보증해 이행하고 구상권을 얻은 보증인은 허위표시를 기초로 새 이해관계를 맺었으므로 제삼자입니다.","허위표시 안에 감추어진 다른 법률행위(은닉행위)는 그 요건을 갖추면 유효하다":"겉으로 꾸민 허위표시 속에 숨은 다른 법률행위는 그 자체의 요건을 갖추면 유효합니다.","허위표시에 따른 법률효과를 침해하는 것처럼 보이는 위법행위가 있는 경우에도 그에 따른 손해배상을 청구할 수 없다":"원래 허위표시의 효과는 무효여서 그 효과를 침해한 행위가 있어도 거기서 손해배상을 청구할 수 없습니다.","허위표시의 당사자와 그 포괄승계인 이외의 자로서 허위표시에 의하여 외형상 형성된 법률관계를 기초로 새로운 법률상 이해관계를 맺은 자":"허위표시가 만든 겉모습의 권리관계를 믿고 새로 법률상 이해관계를 맺은 사람이 보호받는 제삼자입니다.","허위표시의 당사자의 포괄승계인":"허위표시를 한 당사자의 상속인 같은 포괄승계인은 당사자와 같은 지위라서 제삼자에 해당하지 않습니다.","허위표시의 무효는 당사자 사이에서는 누구에게나 주장할 수 있는 절대적 무효이다. 제3자에 대해서는 선의의 제3자에게 대항하지 못한다는 한도에서 상대적이다":"당사자 사이에서는 누구나 무효를 주장하지만 선의의 제삼자에게는 무효를 주장하지 못하는 면에서 상대적입니다.","현저한 불균형이 있어도 궁박·경솔·무경험이 추정되지 않는다":"가치가 크게 어긋나 보여도 그것만으로 피해자의 약점이 있었다고 추정하지는 않습니다.","현존이익이 없다는 점의 증명책임은 반환의무자인 의사무능력자(무능력자 쪽)에게 있다. 상대방에게 현존이익의 증명책임이 있는 것이 아니다":"이익이 남아 있지 않다는 사실은 반환하는 무능력자 쪽이 증명해야 하고 상대가 증명할 일이 아닙니다.","현존하지 않는 장래의 채권을 시효진행이 개시되기 전에 미리 승인하는 것은 허용되지 않는다":"아직 생기지 않은 장래 채권을 시효가 시작되기도 전에 미리 승인하는 것은 인정되지 않습니다.","형사사건에서 변호사 성공보수 약정(형사사건 성공보수)":"형사사건의 결과에 따라 변호사에게 성공보수를 주기로 한 약정은 사회질서에 어긋나 무효로 봅니다.","확정, 가능, 적법, 사회적 타당성":"법률행위의 내용은 정해져 있어야 하고 실현할 수 있어야 하며 법에 맞고 사회적으로 타당해야 효력이 있습니다.","확정판결에 따른 강제집행도 특별한 사정이 있으면 권리남용이 될 수 있다":"확정판결로 한 강제집행이라도 특별한 사정이 있으면 권리남용으로 평가될 수 있어요."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
